public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static string Hex(byte[] b, int n) { return System.Convert.ToHexString(b, 0, n); }

    static ActionPacket Make(uint tick, int id, float x, float y, int skill, string name)
    {
        ActionPacket p = default;
        p.Tick = tick; p.EntityId = (ushort)id; p.X = x; p.Y = y; p.SkillId = (short)skill; p.Name = name;
        return p;
    }

    static void Put(byte[] b, int at, uint v, int size) { for (int i = 0; i < size; i++) b[at + i] = (byte)(v >> (8 * i)); }

    // 기준 인코더: 시프트로 한 바이트씩 쓴다
    static byte[] Ref(ActionPacket p)
    {
        byte[] n = System.Text.Encoding.UTF8.GetBytes(p.Name ?? "");
        byte[] b = new byte[18 + n.Length];
        Put(b, 0, p.Tick, 4); Put(b, 4, p.EntityId, 2);
        Put(b, 6, (uint)System.BitConverter.SingleToInt32Bits(p.X), 4);
        Put(b, 10, (uint)System.BitConverter.SingleToInt32Bits(p.Y), 4);
        Put(b, 14, (ushort)p.SkillId, 2); Put(b, 16, (uint)n.Length, 2);
        n.CopyTo(b, 18);
        return b;
    }

    static string Same(ActionPacket g, ActionPacket e)
    {
        if (g.Tick != e.Tick) return "Tick 기대 " + e.Tick + " / 결과 " + g.Tick;
        if (g.EntityId != e.EntityId) return "EntityId 기대 " + e.EntityId + " / 결과 " + g.EntityId;
        if (System.BitConverter.SingleToInt32Bits(g.X) != System.BitConverter.SingleToInt32Bits(e.X)) return "X 기대 " + e.X + " / 결과 " + g.X;
        if (System.BitConverter.SingleToInt32Bits(g.Y) != System.BitConverter.SingleToInt32Bits(e.Y)) return "Y 기대 " + e.Y + " / 결과 " + g.Y;
        if (g.SkillId != e.SkillId) return "SkillId 기대 " + e.SkillId + " / 결과 " + g.SkillId;
        if (g.Name != (e.Name ?? "")) return "Name 기대 \"" + (e.Name ?? "") + "\" / 결과 \"" + g.Name + "\"";
        return null;
    }

    static byte[] Filled(int n) { byte[] b = new byte[n]; System.Array.Fill(b, (byte)0xEE); return b; }

    static string WriteMatches(ActionPacket p)
    {
        byte[] want = Ref(p);
        byte[] buf = Filled(want.Length + 6);
        int w;
        if (!PacketCodec.TryWrite(buf, p, out w)) return "충분한 버퍼인데 TryWrite 가 false";
        if (w != want.Length) return "written 기대 " + want.Length + " / 결과 " + w;
        if (Hex(buf, w) != Hex(want, want.Length)) return "바이트 기대 " + Hex(want, want.Length) + " / 결과 " + Hex(buf, w);
        for (int i = w; i < buf.Length; i++) if (buf[i] != 0xEE) return "written 뒤쪽 바이트(인덱스 " + i + ")를 건드림";
        return null;
    }

    static long MeasureWrite(ActionPacket p, byte[] buf, int n)
    {
        int w;
        for (int i = 0; i < 300; i++) PacketCodec.TryWrite(buf, p, out w);
        long before = System.GC.GetAllocatedBytesForCurrentThread();
        for (int i = 0; i < n; i++) PacketCodec.TryWrite(buf, p, out w);
        return System.GC.GetAllocatedBytesForCurrentThread() - before;
    }

    public static void Main()
    {
        Run("layout-exact-bytes", () =>
        {
            byte[] buf = Filled(64);
            int w;
            if (!PacketCodec.TryWrite(buf, Make(0x11223344, 0xABCD, 1.0f, -2.5f, -2, "Hi"), out w)) return "TryWrite 가 false";
            string want = "44332211CDAB0000803F000020C0FEFF02004869";
            if (w != 20) return "written 기대 20 / 결과 " + w;
            return Hex(buf, w) == want ? null : "기대 " + want + " / 결과 " + Hex(buf, w);
        });

        Run("roundtrip-utf8-name", () =>
        {
            ActionPacket p = Make(4000000000, 65535, -0.0f, 12345.678f, -1, "검사A");
            byte[] buf = Filled(64);
            int w, c; ActionPacket q;
            if (!PacketCodec.TryWrite(buf, p, out w)) return "TryWrite 가 false";
            if (w != 25) return "\"검사A\" 는 UTF-8 7바이트: written 기대 25 / 결과 " + w;
            if (buf[16] != 7 || buf[17] != 0) return "NameLen 필드 기대 7(바이트 수) / 결과 " + (buf[16] | (buf[17] << 8));
            if (!PacketCodec.TryRead(new System.ReadOnlySpan<byte>(buf, 0, w), out q, out c)) return "TryRead 가 false";
            if (c != w) return "consumed 기대 " + w + " / 결과 " + c;
            return Same(q, p);
        });

        Run("write-buffer-too-small", () =>
        {
            ActionPacket p = Make(7, 3, 1.5f, 2.5f, 10, "Knight");
            for (int len = 0; len < 24; len++)
            {
                byte[] buf = Filled(24);
                int w;
                if (PacketCodec.TryWrite(new System.Span<byte>(buf, 0, len), p, out w)) return "필요 24바이트, dst " + len + "바이트인데 true";
                if (w != 0) return "실패 시 written 기대 0 / 결과 " + w + " (dst " + len + "바이트)";
                for (int i = 0; i < 24; i++) if (buf[i] != 0xEE) return "실패했는데 dst 를 수정함 (dst " + len + "바이트, 인덱스 " + i + ")";
            }
            byte[] exact = Filled(24);
            int w2;
            if (!PacketCodec.TryWrite(exact, p, out w2) || w2 != 24) return "dst 가 정확히 24바이트일 때 성공해야 함";
            return null;
        });

        Run("name-length-limits", () =>
        {
            string e = WriteMatches(Make(1, 1, 0f, 0f, 0, new string('a', 32)));
            if (e != null) return "32바이트 이름: " + e;
            e = WriteMatches(Make(1, 1, 0f, 0f, 0, new string('가', 10) + "ab"));
            if (e != null) return "한글 10자 + ab (32바이트): " + e;
            e = WriteMatches(Make(1, 1, 0f, 0f, 0, null));
            if (e != null) return "Name = null 은 빈 문자열로 써야 함: " + e;
            byte[] buf = Filled(128);
            int w;
            if (PacketCodec.TryWrite(buf, Make(1, 1, 0f, 0f, 0, new string('a', 33)), out w) || w != 0) return "33바이트 이름은 false, written 0 이어야 함";
            if (PacketCodec.TryWrite(buf, Make(1, 1, 0f, 0f, 0, new string('가', 11)), out w) || w != 0) return "한글 11자는 33바이트이므로 false 여야 함";
            for (int i = 0; i < buf.Length; i++) if (buf[i] != 0xEE) return "이름 초과로 실패했는데 dst 를 수정함";
            return null;
        });

        Run("read-truncated-or-lying-length", () =>
        {
            byte[] full = Ref(Make(99, 42, 3f, 4f, 5, "Mage"));
            ActionPacket q; int c;
            for (int len = 0; len < full.Length; len++)
            {
                if (PacketCodec.TryRead(new System.ReadOnlySpan<byte>(full, 0, len), out q, out c)) return "22바이트 패킷의 앞 " + len + "바이트만 줬는데 true";
                if (c != 0) return "실패 시 consumed 기대 0 / 결과 " + c;
                if (q.Name != null || q.Tick != 0) return "실패 시 p 는 default 여야 함";
            }
            byte[] lie = new byte[18 + 40];
            lie[16] = 0xFF; lie[17] = 0xFF;
            if (PacketCodec.TryRead(lie, out q, out c)) return "NameLen = 65535 인데 true";
            lie[16] = 33; lie[17] = 0;
            if (PacketCodec.TryRead(lie, out q, out c)) return "NameLen = 33 (상한 초과, 바이트는 충분)인데 true";
            lie[16] = 32;
            if (!PacketCodec.TryRead(lie, out q, out c) || c != 50) return "NameLen = 32 는 성공하고 consumed 50 이어야 함";
            return null;
        });

        Run("read-consecutive-packets", () =>
        {
            ActionPacket a = Make(100, 1, 1f, 2f, -1, "궁수"), b = Make(101, 2, -3f, 4f, 7, "");
            byte[] ra = Ref(a), rb = Ref(b);
            byte[] all = new byte[ra.Length + rb.Length + 3];
            ra.CopyTo(all, 0); rb.CopyTo(all, ra.Length);
            ActionPacket q; int c;
            if (!PacketCodec.TryRead(all, out q, out c)) return "첫 패킷 TryRead 가 false (뒤에 남는 바이트는 무시해야 함)";
            if (c != ra.Length) return "첫 패킷 consumed 기대 " + ra.Length + " / 결과 " + c;
            string e = Same(q, a); if (e != null) return "첫 패킷 " + e;
            int c2;
            if (!PacketCodec.TryRead(new System.ReadOnlySpan<byte>(all, c, all.Length - c), out q, out c2)) return "둘째 패킷 TryRead 가 false";
            if (c2 != 18) return "둘째 패킷 consumed 기대 18 / 결과 " + c2;
            return Same(q, b);
        });

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(20261122);
            string pool = "abXY09 _가나다검궁법사あ";
            for (int k = 0; k < 400; k++)
            {
                int n = rng.Next(0, 11);
                char[] cs = new char[n];
                for (int i = 0; i < n; i++) cs[i] = pool[rng.Next(pool.Length)];
                ActionPacket p = Make((uint)rng.NextInt64(0, 4294967296L), rng.Next(65536),
                    (float)(rng.NextDouble() * 2000 - 1000), (float)(rng.NextDouble() * 2000 - 1000), rng.Next(-1, 300), new string(cs));
                string e = WriteMatches(p);
                if (e != null) return k + "번째(이름 \"" + p.Name + "\"): " + e;
                ActionPacket q; int c;
                byte[] r = Ref(p);
                if (!PacketCodec.TryRead(r, out q, out c) || c != r.Length) return k + "번째: TryRead 실패 또는 consumed 불일치";
                e = Same(q, p);
                if (e != null) return k + "번째: " + e;
            }
            return null;
        });

        Run("write-no-allocation", () =>
        {
            long bytes = MeasureWrite(Make(123456, 77, 10.5f, -20.25f, 3, "검사Knight"), new byte[64], 2000);
            return bytes < 2048 ? null : "TryWrite 2000회 동안 힙 할당 " + bytes + "바이트 (기대: 0)";
        });
    }
}

