public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    // renderTime 에서 (ex, ey) 가 나와야 한다. 허용 오차 0.001
    static string At(SnapshotBuffer b, long t, double ex, double ey)
    {
        float x, y;
        if (!b.TrySample(t, out x, out y)) return "t=" + t + " 에서 TrySample 이 false";
        if (System.Math.Abs(x - ex) > 1e-3 || System.Math.Abs(y - ey) > 1e-3 || float.IsNaN(x) || float.IsNaN(y))
            return "t=" + t + " 기대 (" + ex + ", " + ey + ") / 결과 (" + x + ", " + y + ")";
        return null;
    }

    public static void Main()
    {
        Run("empty-buffer", () =>
        {
            var b = new SnapshotBuffer(8);
            float x = 9f, y = 9f;
            if (b.Count != 0) return "빈 버퍼의 Count 가 0 이 아님";
            if (b.TrySample(100, out x, out y)) return "빈 버퍼인데 TrySample 이 true";
            return x == 0f && y == 0f ? null : "빈 버퍼의 출력은 (0, 0) 이어야 함 / 결과 (" + x + ", " + y + ")";
        });

        Run("single-snapshot", () =>
        {
            var b = new SnapshotBuffer(8);
            if (!b.Add(1000, 3f, -4f)) return "첫 Add 가 false";
            if (b.Count != 1) return "Count 기대 1 / 결과 " + b.Count;
            return At(b, 900, 3, -4) ?? At(b, 1000, 3, -4) ?? At(b, 5000, 3, -4);
        });

        Run("lerp-between-two", () =>
        {
            var b = new SnapshotBuffer(8);
            b.Add(1000, 0f, 0f); b.Add(1100, 10f, -20f); b.Add(1200, 10f, 20f);
            return At(b, 1050, 5, -10) ?? At(b, 1025, 2.5, -5) ?? At(b, 1099, 9.9, -19.8)
                ?? At(b, 1100, 10, -20) ?? At(b, 1150, 10, 0) ?? At(b, 1001, 0.1, -0.2);
        });

        Run("clamp-outside-range", () =>
        {
            var b = new SnapshotBuffer(8);
            b.Add(1000, 1f, 1f); b.Add(1100, 2f, 4f); b.Add(1200, 4f, 16f);
            return At(b, 999, 1, 1) ?? At(b, -50, 1, 1) ?? At(b, 1000, 1, 1)
                ?? At(b, 1200, 4, 16) ?? At(b, 1201, 4, 16) ?? At(b, 99999, 4, 16);
        });

        Run("reject-out-of-order-and-duplicate", () =>
        {
            var b = new SnapshotBuffer(8);
            b.Add(1000, 0f, 0f); b.Add(1100, 10f, 10f);
            if (b.Add(1100, 99f, 99f)) return "같은 시각(1100) 중복 스냅샷인데 Add 가 true";
            if (b.Add(1050, 99f, 99f)) return "늦게 도착한 과거 스냅샷(1050)인데 Add 가 true";
            if (b.Add(900, 99f, 99f)) return "가장 오래된 것보다 과거(900)인데 Add 가 true";
            if (b.Count != 2) return "버린 뒤 Count 기대 2 / 결과 " + b.Count;
            string e = At(b, 1050, 5, 5) ?? At(b, 1100, 10, 10) ?? At(b, 900, 0, 0);
            if (e != null) return "버린 스냅샷이 결과에 영향을 줌: " + e;
            if (!b.Add(1101, 20f, 20f) || b.Count != 3) return "더 새로운 스냅샷(1101)은 받아야 함";
            return At(b, 1101, 20, 20);
        });

        Run("capacity-evicts-oldest", () =>
        {
            var b = new SnapshotBuffer(3);
            for (int i = 0; i < 5; i++) if (!b.Add(100 * i, i, 10 * i)) return i + "번째 Add 가 false";
            if (b.Count != 3) return "capacity 3 에 5개 추가 후 Count 기대 3 / 결과 " + b.Count;
            string e = At(b, 0, 2, 20) ?? At(b, 150, 2, 20) ?? At(b, 250, 2.5, 25) ?? At(b, 350, 3.5, 35) ?? At(b, 400, 4, 40);
            if (e != null) return e;
            for (int i = 5; i < 40; i++) b.Add(100 * i, i, 10 * i);
            return b.Count != 3 ? "Count 기대 3 / 결과 " + b.Count : At(b, 3650, 37, 370) ?? At(b, 3750, 37.5, 375) ?? At(b, 3890, 38.9, 389);
        });

        Run("lost-snapshot-gap-and-large-timestamps", () =>
        {
            // 1150 스냅샷이 유실됨: 1100 과 1300 사이는 그 둘로 보간한다
            var b = new SnapshotBuffer(8);
            b.Add(1000, 0f, 0f); b.Add(1100, 10f, 0f); b.Add(1300, 30f, 40f);
            string e = At(b, 1200, 20, 20) ?? At(b, 1150, 15, 10) ?? At(b, 1250, 25, 30);
            if (e != null) return e;
            // 서버 시각이 큰 값(Unix ms)이어도 보간 비율이 정확해야 한다
            long T = 1700000000000L;
            var c = new SnapshotBuffer(8);
            c.Add(T, 100f, 200f); c.Add(T + 50, 110f, 180f); c.Add(T + 100, 120f, 200f);
            return At(c, T + 25, 105, 190) ?? At(c, T + 60, 112, 184) ?? At(c, T + 99, 119.8, 199.6);
        });

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(4242);
            for (int run = 0; run < 200; run++)
            {
                int cap = rng.Next(2, 12);
                var b = new SnapshotBuffer(cap);
                var model = new System.Collections.Generic.List<double[]>();   // {t, x, y}, 시간순
                long now = rng.Next(0, 2) == 0 ? rng.Next(0, 1000) : 1700000000000L + rng.Next(0, 1000);
                for (int step = 0; step < 60; step++)
                {
                    long t = now + rng.Next(-80, 120);
                    float x = rng.Next(-1000, 1001), y = rng.Next(-1000, 1001);
                    bool expectOk = model.Count == 0 || t > (long)model[model.Count - 1][0];
                    bool ok = b.Add(t, x, y);
                    if (ok != expectOk) return run + "회차: Add(t=" + t + ") 기대 " + expectOk + " / 결과 " + ok;
                    if (ok)
                    {
                        model.Add(new double[] { t, x, y });
                        if (model.Count > cap) model.RemoveAt(0);
                        now = t;
                    }
                    if (b.Count != model.Count) return run + "회차: Count 기대 " + model.Count + " / 결과 " + b.Count;
                    long first = (long)model[0][0], last = (long)model[model.Count - 1][0];
                    long rt = first - 30 + (long)(rng.NextDouble() * (last - first + 60));
                    double ex, ey;
                    if (rt <= first) { ex = model[0][1]; ey = model[0][2]; }
                    else if (rt >= last) { ex = model[model.Count - 1][1]; ey = model[model.Count - 1][2]; }
                    else
                    {
                        int i = 0;
                        while ((long)model[i + 1][0] <= rt) i++;
                        double u = (rt - model[i][0]) / (model[i + 1][0] - model[i][0]);
                        ex = model[i][1] + (model[i + 1][1] - model[i][1]) * u;
                        ey = model[i][2] + (model[i + 1][2] - model[i][2]) * u;
                    }
                    float gx, gy;
                    if (!b.TrySample(rt, out gx, out gy)) return run + "회차: TrySample 이 false";
                    if (System.Math.Abs(gx - ex) > 0.02 || System.Math.Abs(gy - ey) > 0.02 || float.IsNaN(gx) || float.IsNaN(gy))
                        return run + "회차 (capacity " + cap + ", 스냅샷 " + model.Count + "개, 구간 " + first + "~" + last + "): t=" + rt + " 기대 (" + ex.ToString("F3") + ", " + ey.ToString("F3") + ") / 결과 (" + gx + ", " + gy + ")";
                }
            }
            return null;
        });
    }
}

