using System;

// RTT(왕복 시간) 표본을 받아 평활 RTT 와 변동 폭을 추정한다.
// 갱신 식은 TCP 의 재전송 타이머 계산법(RFC 6298)을 따른다.
public sealed class RttEstimator
{
    private const double Alpha = 1.0 / 8.0;   // SRTT 가 새 표본 쪽으로 움직이는 비율
    private const double Beta = 1.0 / 4.0;    // RTTVAR 가 새 편차 쪽으로 움직이는 비율

    public bool HasSample { get; private set; }
    public double SmoothedRttMs { get; private set; }   // SRTT
    public double RttVarMs { get; private set; }        // RTTVAR: RTT 가 얼마나 흔들리는지

    public void AddSample(double rttMs)
    {
        if (double.IsNaN(rttMs) || rttMs < 0) return;

        if (!HasSample)
        {
            SmoothedRttMs = rttMs;
            RttVarMs = rttMs / 2;
            HasSample = true;
            return;
        }

        // 순서가 중요하다: RTTVAR 를 먼저, 갱신 전의 SRTT 로 계산한다.
        RttVarMs = (1 - Beta) * RttVarMs + Beta * Math.Abs(SmoothedRttMs - rttMs);
        SmoothedRttMs = (1 - Alpha) * SmoothedRttMs + Alpha * rttMs;
    }

    public double ResendTimeoutMs(double minMs, double maxMs)
    {
        if (!HasSample) return maxMs;
        return Math.Clamp(SmoothedRttMs + 4 * RttVarMs, minMs, maxMs);
    }
}

// 핑을 보낸 시각을 기억했다가 퐁이 오면 RTT 표본을 만든다.
public sealed class PingTracker
{
    private readonly double[] _sentAtMs = new double[256];
    private readonly bool[] _waiting = new bool[256];

    public void OnPingSent(byte id, double nowMs)
    {
        _sentAtMs[id] = nowMs;
        _waiting[id] = true;
    }

    public bool OnPongReceived(byte id, double nowMs, RttEstimator estimator)
    {
        if (!_waiting[id]) return false;      // 보낸 적 없는 id, 또는 중복 퐁
        _waiting[id] = false;                 // 같은 퐁이 다시 와도 표본은 한 번만

        // 보낸 시각과 받은 시각을 모두 "내 시계"로 잰다. 상대 시계와 맞출 필요가 없다.
        estimator.AddSample(nowMs - _sentAtMs[id]);
        return true;
    }
}

