using System;

// 범위 [min, max] 의 실수를 bits 비트 정수(0 ~ 2^bits - 1)로 양자화한다.
// 호출자가 보장하는 것: min < max (둘 다 유한), 1 <= bits <= 16, value 는 NaN 이 아니다(±Infinity 는 올 수 있다).
public static class Quantizer
{
    public static uint Quantize(float value, float min, float max, int bits)
    {
        uint maxInt = (1u << bits) - 1u;
        double clamped = Math.Clamp(value, min, max);            // 정수로 바꾸기 전에 먼저 자른다(±Infinity 포함)
        double t = (clamped - min) / ((double)max - min);        // 0 ~ 1
        // Math.Round 의 기본 규칙(중간값을 짝수 쪽으로)은 이 프로토콜의 규칙과 다르므로 쓰지 않는다.
        return (uint)Math.Floor(t * maxInt + 0.5);
    }

    public static float Dequantize(uint q, float min, float max, int bits)
    {
        uint maxInt = (1u << bits) - 1u;
        if (q > maxInt) q = maxInt;                              // 범위를 벗어난 정수는 믿지 않는다
        return (float)(min + (double)q / maxInt * ((double)max - min));
    }
}

