public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static string Q(float v, float min, float max, int bits, uint want)
    {
        uint got = Quantizer.Quantize(v, min, max, bits);
        return got == want ? null : "Quantize(" + v + ", " + min + ", " + max + ", " + bits + ") 기대 " + want + " / 결과 " + got;
    }

    static string D(uint q, float min, float max, int bits, float want)
    {
        float got = Quantizer.Dequantize(q, min, max, bits);
        return System.Math.Abs(got - want) <= 1e-4f ? null : "Dequantize(" + q + ", " + min + ", " + max + ", " + bits + ") 기대 " + want + " / 결과 " + got;
    }

    // [min,max] 를 samples 등분한 모든 점에서 왕복 오차 <= step/2 (부동소수점 여유 2%) 와 단조성을 확인한다
    static string Sweep(float min, float max, int bits, int samples)
    {
        uint maxInt = (1u << bits) - 1u;
        double step = ((double)max - min) / maxInt;
        uint prev = 0;
        for (int i = 0; i <= samples; i++)
        {
            float x = (float)(min + ((double)max - min) * i / samples);
            uint q = Quantizer.Quantize(x, min, max, bits);
            if (q > maxInt) return "Quantize(" + x + ") = " + q + " 가 최댓값 " + maxInt + " 을 넘음";
            if (q < prev) return "단조성 위반: x=" + x + " 에서 q 가 " + prev + " -> " + q + " 로 줄어듦";
            prev = q;
            double err = System.Math.Abs((double)Quantizer.Dequantize(q, min, max, bits) - x);
            if (err > step * 0.51) return "x=" + x + " 왕복 오차 " + err.ToString("G4") + " > step/2 = " + (step / 2).ToString("G4") + " (범위 " + min + "~" + max + ", " + bits + "비트)";
        }
        return prev == maxInt ? null : "x=max 에서 q 기대 " + maxInt + " / 결과 " + prev;
    }

    public static void Main()
    {
        Run("endpoints-exact", () =>
            Q(-512f, -512f, 512f, 16, 0) ?? Q(512f, -512f, 512f, 16, 65535) ?? Q(0f, 0f, 32f, 10, 0) ?? Q(32f, 0f, 32f, 10, 1023)
            ?? D(0, -512f, 512f, 16, -512f) ?? D(65535, -512f, 512f, 16, 512f) ?? D(0, 0f, 32f, 10, 0f) ?? D(1023, 0f, 32f, 10, 32f));

        Run("small-grid-values", () =>
        {
            for (uint k = 0; k <= 3; k++)
            {
                string e = Q(k, 0f, 3f, 2, k) ?? D(k, 0f, 3f, 2, k);
                if (e != null) return e;
            }
            return Q(100.25f, 0f, 255f, 8, 100) ?? Q(100.75f, 0f, 255f, 8, 101) ?? Q(-3f, -4f, 4f, 3, 1) ?? D(1, -4f, 4f, 3, -4f + 8f / 7f);
