using System;

public static class SequenceMath
{
    // a 가 b 보다 "더 최신"이면 true.
    // 16비트 시퀀스 번호는 65535 다음에 0 으로 돌아간다.
    public static bool IsNewer(ushort a, ushort b)
    {
        int diff = a - b;
        return diff > 0 && diff < 32768;
    }
}

// 수신한 패킷 번호를 기억해 중복과 너무 오래된 패킷을 걸러 낸다.
// 연결(상대)마다 인스턴스 하나를 쓴다.
public sealed class DuplicateFilter
{
    public const int WindowSize = 64;

    private bool _hasAny;
    private ushort _latest;   // 지금까지 받은 것 중 가장 최신 번호
    private ulong _mask;      // 비트 n 이 1 이면 (_latest - n) 번 패킷을 이미 받았다

    // 처음 받는 유효한 패킷이면 true(처리한다), 중복이거나 창 밖의 오래된 패킷이면 false(버린다).
    public bool Accept(ushort seq)
    {
        if (!_hasAny)
        {
            _hasAny = true;
            _latest = seq;
            _mask = 1UL;
            return true;
        }

        if (SequenceMath.IsNewer(seq, _latest))
        {
            int shift = seq - _latest;
            _mask = (_mask << shift) | 1UL;
            _latest = seq;
            return true;
        }

        int behind = _latest - seq;
        if (behind >= WindowSize) return false;

        ulong bit = 1UL << behind;
        if ((_mask & bit) != 0) return false;
        _mask |= bit;
        return true;
    }
}

