using System;

public static class SequenceMath
{
    // a 가 b 보다 "더 최신"이면 true.
    // 정의: d = (a - b) mod 65536 일 때 0 < d < 32768.
    // d == 0(같은 번호)과 d == 32768(정확히 반 바퀴, 방향을 알 수 없음)은 양쪽 모두 false.
    public static bool IsNewer(ushort a, ushort b)
    {
        // ushort 끼리의 뺄셈 결과는 int 다. ushort 로 되돌려야 mod 65536 차이가 된다.
        ushort d = unchecked((ushort)(a - b));
        return d != 0 && d < 32768;
    }
}

// 수신한 패킷 번호를 기억해 중복과 너무 오래된 패킷을 걸러 낸다.
// 연결(상대)마다 인스턴스 하나를 쓴다.
public sealed class DuplicateFilter
{
    public const int WindowSize = 64;

    private bool _hasAny;
    private ushort _latest;   // 지금까지 받은 것 중 가장 최신 번호
    private ulong _mask;      // 비트 n 이 1 이면 (_latest - n) 번 패킷을 이미 받았다

    public bool Accept(ushort seq)
    {
        if (!_hasAny)
        {
            _hasAny = true;
            _latest = seq;
            _mask = 1UL;
            return true;
        }

        if (SequenceMath.IsNewer(seq, _latest))
        {
            // 몇 칸 앞섰는가 (1 ~ 32767). 랩어라운드를 넘어도 mod 65536 차이라 그대로 맞다.
            int shift = unchecked((ushort)(seq - _latest));
            // ulong 의 시프트 수는 하위 6비트만 쓰인다: 64칸 이상은 직접 0 으로 만든다.
            _mask = shift >= WindowSize ? 0UL : _mask << shift;
            _mask |= 1UL;
            _latest = seq;
            return true;
        }

        // 몇 칸 뒤처졌는가 (0 ~ 32768). int 뺄셈을 그대로 쓰면 랩어라운드 뒤에 음수가 된다.
        int behind = unchecked((ushort)(_latest - seq));
        if (behind >= WindowSize) return false;        // 창 밖: 받았는지 알 수 없으므로 버린다

        ulong bit = 1UL << behind;
        if ((_mask & bit) != 0) return false;          // 이미 받은 번호
        _mask |= bit;
        return true;
    }
}

