                long baseNo = 65536L * 3 - 300 + Next(200);         // 진짜(랩 없는) 번호: 실행 중에 16비트 경계를 넘는다
                var seen = new System.Collections.Generic.HashSet<long>();
                long latest = -1;
                long cursor = baseNo;
                for (int i = 0; i < 1500; i++)
                {
                    long no;
                    uint kind = Next(10);
                    if (latest < 0 || kind < 5) { cursor += 1 + (Next(20) == 0 ? Next(150) : 0); no = cursor; }   // 새 패킷(가끔 큰 건너뜀)
                    else if (kind < 8) no = latest - Next(80);         // 늦게 온 패킷 또는 중복
                    else { cursor += 1 + Next(4); no = cursor - Next(3); }  // 약간 뒤섞인 새 패킷
                    bool want;
                    if (latest < 0) { want = true; latest = no; }
