using System;
using System.Collections.Generic;

// ───────── 제공 코드: 수정하지 마세요 ─────────

// UDP 데이터그램 하나에 해당한다. Data 는 메시지 하나, Ack 는 "Seq 번 메시지를 받았다"는 확인이다.
public readonly struct Packet
{
    public readonly bool IsAck;
    public readonly ushort Seq;
    public readonly byte[] Payload;   // Ack 일 때는 null

    private Packet(bool isAck, ushort seq, byte[] payload) { IsAck = isAck; Seq = seq; Payload = payload; }

    public static Packet Data(ushort seq, byte[] payload) => new Packet(false, seq, payload);
    public static Packet Ack(ushort seq) => new Packet(true, seq, null);
}

// 한 방향의 가짜 네트워크. 패킷의 운명은 고정된 선형 합동 생성기로 정해지므로
// 같은 seed 와 같은 호출 순서라면 언제나 같은 결과가 나온다(System.Random 을 쓰지 않는다).
//   Send 한 번마다 roll = 0 ~ 9 를 하나 뽑는다.
//     0, 1    : 유실
//     2, 3    : 9틱 뒤 도착(뒤에 보낸 패킷보다 늦게 도착한다)
//     4 ~ 8   : 2틱 뒤 도착
//     9       : 2틱 뒤와 3틱 뒤에 한 번씩, 두 번 도착(중복)
public sealed class LossyChannel
{
    private struct InFlight { public long Due; public long Order; public Packet Packet; }

    private readonly List<InFlight> _inFlight = new List<InFlight>();
    private uint _state;
    private long _order;

    public LossyChannel(uint seed) { _state = seed; }

    public void Send(Packet packet, long now)
    {
        _state = unchecked(_state * 1664525u + 1013904223u);
        uint roll = (_state >> 16) % 10u;
        if (roll < 2) return;
        long delay = roll < 4 ? 9 : 2;
        _inFlight.Add(new InFlight { Due = now + delay, Order = _order++, Packet = packet });
        if (roll == 9) _inFlight.Add(new InFlight { Due = now + delay + 1, Order = _order++, Packet = packet });
    }

    // 도착 시각이 now 이하인 패킷을 (도착 시각, 넣은 순서) 오름차순으로 arrived 에 추가한다.
    public void Deliver(long now, List<Packet> arrived)
    {
        while (true)
        {
            int best = -1;
            for (int i = 0; i < _inFlight.Count; i++)
            {
                if (_inFlight[i].Due > now) continue;
                if (best < 0 || _inFlight[i].Due < _inFlight[best].Due ||
                    (_inFlight[i].Due == _inFlight[best].Due && _inFlight[i].Order < _inFlight[best].Order)) best = i;
            }
            if (best < 0) return;
            arrived.Add(_inFlight[best].Packet);
            _inFlight.RemoveAt(best);
        }
    }
}

// ───────── 여기부터 구현 ─────────

// 신뢰성·순서 보장 메시지 계층의 한쪽 끝. 보내기와 받기를 모두 한다.
// 시각(now)은 정수 틱이고, 내보낼 패킷은 outgoing 에 추가만 한다(실제 전송은 호출자가 한다).
public sealed class ReliableEndpoint
{
    public const int WindowSize = 64;

    // firstSeq: 양쪽이 접속 때 합의한 첫 메시지 번호(내가 보낼 첫 번호이자 상대에게서 받을 첫 번호).
    // resendDelay: 재전송 간격(틱, 1 이상).
    public ReliableEndpoint(ushort firstSeq, int resendDelay)
    {
        throw new NotImplementedException();
    }

    // 보냈지만 아직 Ack 를 받지 못한 메시지 수.
    public int PendingCount => throw new NotImplementedException();

    // 메시지를 보낸다. 창이 가득 차 있으면 아무것도 하지 않고 false.
    // 성공하면 번호를 붙여 Data 패킷 하나를 outgoing 에 추가하고 true.
    public bool Send(byte[] payload, long now, List<Packet> outgoing)
    {
        throw new NotImplementedException();
    }

    // 네트워크에서 도착한 패킷 하나를 처리한다.
    // 응답으로 보낼 Ack 는 outgoing 에, 순서가 맞아 애플리케이션에 넘길 메시지는 delivered 에 추가한다.
    public void Receive(Packet packet, List<Packet> outgoing, List<byte[]> delivered)
    {
        throw new NotImplementedException();
    }

    // 재전송할 때가 된 메시지를 번호가 오래된 것부터 outgoing 에 추가한다.
    public void Tick(long now, List<Packet> outgoing)
    {
        throw new NotImplementedException();
    }
}

