        _inFlight.Add(new InFlight { Due = now + delay, Order = _order++, Packet = packet });
        if (roll == 9) _inFlight.Add(new InFlight { Due = now + delay + 1, Order = _order++, Packet = packet });
    }

    // 도착 시각이 now 이하인 패킷을 (도착 시각, 넣은 순서) 오름차순으로 arrived 에 추가한다.
    public void Deliver(long now, List<Packet> arrived)
