// ───────── 여기부터 구현 ─────────

// 신뢰성·순서 보장 메시지 계층의 한쪽 끝. 보내기와 받기를 모두 한다.
// 시각(now)은 정수 틱이고, 내보낼 패킷은 outgoing 에 추가만 한다(실제 전송은 호출자가 한다).
public sealed class ReliableEndpoint
{
    public const int WindowSize = 64;

    private readonly int _resendDelay;

    // 송신 창: [_sendBase, _sendNext) 가 "보냈고 아직 정리되지 않은" 번호 구간이다. 길이는 WindowSize 이하.
    // 슬롯은 seq % WindowSize. 65536 이 64 의 배수라서 번호가 0 으로 돌아가도 슬롯 순서가 이어진다.
    private readonly byte[][] _sendPayload = new byte[WindowSize][];
    private readonly long[] _sendTime = new long[WindowSize];
    private readonly bool[] _sendPending = new bool[WindowSize];
    private ushort _sendBase;     // Ack 를 못 받은 가장 오래된 번호 (없으면 _sendNext 와 같다)
    private ushort _sendNext;     // 다음에 붙일 번호
    private int _pendingCount;

    // 수신 창: [_recvNext, _recvNext + WindowSize) 만 보관한다.
    private readonly byte[][] _recvPayload = new byte[WindowSize][];
    private readonly bool[] _recvHas = new bool[WindowSize];
    private ushort _recvNext;     // 애플리케이션에 다음으로 넘길 번호

    public ReliableEndpoint(ushort firstSeq, int resendDelay)
    {
        if (resendDelay < 1) throw new ArgumentOutOfRangeException(nameof(resendDelay));
        _resendDelay = resendDelay;
        _sendBase = _sendNext = _recvNext = firstSeq;
    }

    public int PendingCount => _pendingCount;

    public bool Send(byte[] payload, long now, List<Packet> outgoing)
    {
        if (payload == null) throw new ArgumentNullException(nameof(payload));

        // 미확인 개수가 아니라 "가장 오래된 미확인 번호부터의 거리"로 제한한다.
        // 그래야 수신 측 창(WindowSize)을 넘는 번호가 네트워크에 나가지 않는다.
        if (unchecked((ushort)(_sendNext - _sendBase)) >= WindowSize) return false;

        int slot = _sendNext % WindowSize;
        _sendPayload[slot] = payload;
        _sendTime[slot] = now;
        _sendPending[slot] = true;
        _pendingCount++;

        outgoing.Add(Packet.Data(_sendNext, payload));
        _sendNext++;                                   // ushort: 65535 다음은 0
        return true;
    }

    public void Receive(Packet packet, List<Packet> outgoing, List<byte[]> delivered)
    {
        if (packet.IsAck) { OnAck(packet.Seq); return; }

        // 기다리는 번호보다 몇 칸 앞인가 (mod 65536)
        ushort ahead = unchecked((ushort)(packet.Seq - _recvNext));

        if (ahead >= WindowSize)
        {
            // 32768 이상이면 과거 번호: 이미 넘긴 메시지의 재전송이다(내 Ack 가 유실됐다). Ack 만 다시 보낸다.
            // 그 사이(64 ~ 32767)는 창을 넘는 미래 번호: 보관할 수 없으므로 Ack 도 보내지 않고 버린다.
            if (ahead >= 32768) outgoing.Add(Packet.Ack(packet.Seq));
            return;
        }

        outgoing.Add(Packet.Ack(packet.Seq));          // 중복이어도 Ack 는 보낸다

        int slot = packet.Seq % WindowSize;
        if (!_recvHas[slot])
        {
            _recvHas[slot] = true;
            _recvPayload[slot] = packet.Payload;
        }

        // 기다리던 번호부터 연속으로 채워진 만큼 순서대로 넘긴다
        while (_recvHas[_recvNext % WindowSize])
        {
            int s = _recvNext % WindowSize;
            delivered.Add(_recvPayload[s]);
            _recvPayload[s] = null;
            _recvHas[s] = false;
            _recvNext++;
        }
    }

    private void OnAck(ushort seq)
    {
        ushort offset = unchecked((ushort)(seq - _sendBase));
        ushort inFlight = unchecked((ushort)(_sendNext - _sendBase));
        if (offset >= inFlight) return;                // 보낸 적 없거나 이미 정리된 번호

        int slot = seq % WindowSize;
        if (!_sendPending[slot]) return;               // 중복 Ack

        _sendPending[slot] = false;
        _sendPayload[slot] = null;
        _pendingCount--;

        // 앞쪽이 확인됐으면 창을 민다
        while (_sendBase != _sendNext && !_sendPending[_sendBase % WindowSize]) _sendBase++;
    }

    public void Tick(long now, List<Packet> outgoing)
    {
        // _sendBase 부터 번호 순서대로: 오래된 메시지가 먼저 나간다
        for (ushort seq = _sendBase; seq != _sendNext; seq++)
        {
            int slot = seq % WindowSize;
            if (!_sendPending[slot]) continue;
            if (now - _sendTime[slot] < _resendDelay) continue;

            outgoing.Add(Packet.Data(seq, _sendPayload[slot]));
            _sendTime[slot] = now;
        }
    }
}

