            const int NA = 400, NB = 90;
            var ends = new[] { new ReliableEndpoint(65300, 12), new ReliableEndpoint(65300, 12) };
            var chan = new[] { new LossyChannel(2026u), new LossyChannel(1122u) };   // chan[i]: i 가 보내는 방향
            var outp = new[] { new System.Collections.Generic.List<Packet>(), new System.Collections.Generic.List<Packet>() };
            var recv = new[] { new System.Collections.Generic.List<byte[]>(), new System.Collections.Generic.List<byte[]>() };
            int[] total = { NA, NB }, sent = { 0, 0 };
            var arrived = new System.Collections.Generic.List<Packet>();
            long now = 0;
            for (; now < 30000; now++)
            {
                for (int i = 0; i < 2; i++)
                {
                    // 애플리케이션: 틱마다 최대 3개씩, 창이 허락하는 만큼 보낸다
                    for (int k = 0; k < 3 && sent[i] < total[i] && ends[i].Send(Msg(sent[i] + i * 1000), now, outp[i]); k++) sent[i]++;
                }
                for (int i = 0; i < 2; i++)
                {
                    arrived.Clear();
                    chan[1 - i].Deliver(now, arrived);
                    foreach (Packet p in arrived) ends[i].Receive(p, outp[i], recv[i]);
                }
                for (int i = 0; i < 2; i++)
                {
                    ends[i].Tick(now, outp[i]);
                    foreach (Packet p in outp[i]) chan[i].Send(p, now);
                    outp[i].Clear();
                }
                if (recv[1].Count >= NA && recv[0].Count >= NB && ends[0].PendingCount == 0 && ends[1].PendingCount == 0) break;
            }
            for (int i = 0; i < 2; i++)
            {
                int want = total[1 - i], offset = (1 - i) * 1000;
                for (int k = 0; k < recv[i].Count && k < want; k++)
                    if (Id(recv[i][k]) != k + offset) return (i == 0 ? "A" : "B") + " 가 받은 " + k + "번째 메시지 기대 #" + (k + offset) + " / 결과 #" + Id(recv[i][k]) + " (순서 어긋남·중복·누락)";
                if (recv[i].Count != want) return (i == 0 ? "A" : "B") + " 가 받은 메시지 수 기대 " + want + " / 결과 " + recv[i].Count + " (" + now + "틱 경과)";
                if (ends[i].PendingCount != 0) return (i == 0 ? "A" : "B") + " 의 PendingCount 가 0 이 되지 않음: " + ends[i].PendingCount;
            }
            for (int i = 0; i < 2; i++)
            {
                ends[i].Tick(now + 100000, outp[i]);
                if (outp[i].Count != 0) return "모든 메시지가 확인된 뒤에도 Tick 이 패킷을 내보냄: " + Show(outp[i]);
            }
            return null;
        });
    }
}

