using System;
using System.Collections.Generic;

public static class SequenceMath
{
    // a 가 b 보다 "더 최신"이면 true (16비트 번호는 65535 다음에 0 으로 돌아간다).
    public static bool IsNewer(ushort a, ushort b)
    {
        ushort d = unchecked((ushort)(a - b));
        return d != 0 && d < 32768;
    }
}

// 받는 쪽: 어떤 패킷을 받았는지 기억했다가, 내가 보내는 패킷의 헤더에 (Ack, AckBits) 로 싣는다.
public sealed class ReceivedTracker
{
    private const int MaskBits = 32;

    public bool HasAny { get; private set; }
    public ushort Ack { get; private set; }

    // n = 1..32 에 대해, (Ack - n) 번 패킷을 받았으면 비트 (n - 1) 이 1.
    public uint AckBits { get; private set; }

    public void OnReceived(ushort seq)
    {
        if (!HasAny)
        {
            HasAny = true;
            Ack = seq;
            AckBits = 0;
            return;
        }

        if (SequenceMath.IsNewer(seq, Ack))
        {
            // 몇 칸 앞섰는가 (1 ~ 32767). ushort 뺄셈은 int 로 계산되므로 ushort 로 되돌린다.
            int ahead = unchecked((ushort)(seq - Ack));

            // 기존 비트는 ahead 칸씩 뒤로 밀린다. uint 의 시프트 수는 하위 5비트만 쓰이므로
            // 32 이상은 직접 0 으로 만든다(uint << 32 는 0 이 아니라 원래 값이다).
            uint shifted = ahead >= MaskBits ? 0u : AckBits << ahead;

            // 방금 전까지의 Ack 는 이제 "새 Ack - ahead" 이므로 비트 (ahead - 1) 자리다.
            if (ahead <= MaskBits) shifted |= 1u << (ahead - 1);

            AckBits = shifted;
            Ack = seq;
            return;
        }

        // 같은 번호이거나 더 오래된 번호. 몇 칸 뒤처졌는가 (0 ~ 32768).
        int behind = unchecked((ushort)(Ack - seq));
        if (behind >= 1 && behind <= MaskBits)
            AckBits |= 1u << (behind - 1);
        // behind == 0: Ack 자체의 중복. behind > 32: 창 밖이라 더는 알릴 방법이 없다.
    }
}

// 보내는 쪽: 보낸 패킷을 기록해 두고, 상대가 보내 온 (ack, ackBits) 로 "도착이 확인된 패킷"을 알아낸다.
public sealed class SentTracker
{
    public const int HistorySize = 256;

    private const byte Empty = 0, Pending = 1, Acked = 2;

    // 번호 s 의 기록은 s % 256 칸에 둔다. 256개 뒤의 번호가 같은 칸을 덮어쓰면서 옛 기록을 잊는다.
    private readonly ushort[] _slotSeq = new ushort[HistorySize];
    private readonly byte[] _slotState = new byte[HistorySize];
    private ushort _next;

    public SentTracker(ushort firstSequence = 0)
    {
        _next = firstSequence;
    }

    public ushort OnSend()
    {
        ushort seq = _next;
        int slot = seq % HistorySize;
        _slotSeq[slot] = seq;
        _slotState[slot] = Pending;
        _next = unchecked((ushort)(_next + 1));
        return seq;
    }

    public int ProcessAcks(ushort ack, uint ackBits, List<ushort> newlyAcked)
    {
        int count = 0;
        if (TryAck(ack)) { newlyAcked.Add(ack); count++; }

        for (int n = 1; n <= 32; n++)
        {
            if ((ackBits & (1u << (n - 1))) == 0) continue;
            ushort seq = unchecked((ushort)(ack - n));
            if (TryAck(seq)) { newlyAcked.Add(seq); count++; }
        }
        return count;
    }

    // seq 가 "보냈고 아직 확인 안 된" 기록이면 확인됨으로 바꾸고 true.
    private bool TryAck(ushort seq)
    {
        int slot = seq % HistorySize;
        if (_slotState[slot] != Pending || _slotSeq[slot] != seq) return false;
        _slotState[slot] = Acked;
        return true;
    }
}

