using System;
using System.Collections.Generic;

public struct InputCmd
{
    public uint Seq;    // 입력 번호. 1 부터 1씩 증가
    public int Dir;     // -1, 0, +1
    public float Dt;    // 이 입력이 적용된 프레임의 길이(초)
}

// 클라이언트와 서버가 함께 쓰는 이동 규칙.
public static class MoveSim
{
    public const float Speed = 8f;   // m/s
    public static float Step(float x, int dir, float dt) => x + dir * Speed * dt;
}

// 내 캐릭터의 예측 이동과 서버 재조정, 그리고 보정이 화면에서 튀지 않게 하는 시각 보정.
public sealed class PredictedPlayer
{
    public const float SnapDistance = 2f;      // 보정 오차가 이보다 크면 부드럽게 따라가지 않고 순간이동한다
    public const float SmoothFactor = 0.9f;    // 렌더 프레임마다 시각 오차에 곱하는 값
    public const float MinOffset = 0.001f;     // 시각 오차가 이보다 작아지면 0 으로 정리한다

    private readonly List<InputCmd> _pending = new List<InputCmd>();
    private uint _nextSeq = 1;
    private uint _lastAckedSeq;
    private float _visualOffset;

    public PredictedPlayer(float startX) { SimX = startX; }

    // 시뮬레이션 위치(예측 결과). 게임 로직은 이 값을 쓴다.
    public float SimX { get; private set; }

    // 화면에 그리는 위치 = 시뮬레이션 위치 + 아직 줄이지 못한 시각 오차.
    public float RenderX => SimX + _visualOffset;

    public int PendingCount => _pending.Count;

    // 이번 프레임의 입력을 바로 적용(예측)하고, 서버로 보낼 명령을 반환한다.
    public InputCmd ApplyInput(int dir, float dt)
    {
        var cmd = new InputCmd { Seq = _nextSeq++, Dir = dir, Dt = dt };
        SimX = MoveSim.Step(SimX, dir, dt);
        _pending.Add(cmd);
        return cmd;
    }

    // 서버 상태 수신: "lastProcessedSeq 번 입력까지 처리한 결과 위치가 serverX 다."
    public void OnServerState(uint lastProcessedSeq, float serverX)
    {
        if (lastProcessedSeq < _lastAckedSeq) return;   // 순서가 뒤바뀌어 늦게 온 옛 상태
        _lastAckedSeq = lastProcessedSeq;

        // 보정 전에 화면에 보이던 위치를 기억해 둔다.
        float before = RenderX;

        // 1) 서버가 처리한 입력(lastProcessedSeq 번 포함)은 serverX 에 이미 들어 있다. 버린다.
        int acked = 0;
        while (acked < _pending.Count && _pending[acked].Seq <= lastProcessedSeq) acked++;
        _pending.RemoveRange(0, acked);

        // 2) 서버 위치에서 출발해 남은 입력을 "그 입력이 만들어질 때의 dt" 로 다시 적용한다.
        SimX = serverX;
        for (int i = 0; i < _pending.Count; i++)
            SimX = MoveSim.Step(SimX, _pending[i].Dir, _pending[i].Dt);

        // 3) 시각 보정. 작은 오차는 화면 위치를 그대로 두고(오프셋으로 흡수) 서서히 줄이고,
        //    큰 오차는 끌고 가지 않고 바로 맞춘다.
        float error = before - SimX;
        _visualOffset = Math.Abs(error) > SnapDistance ? 0f : error;
    }

    // 렌더 프레임마다 한 번 호출한다. 시각 오차를 조금씩 줄인다.
    public void UpdateVisual()
    {
        _visualOffset *= SmoothFactor;
        if (Math.Abs(_visualOffset) < MinOffset) _visualOffset = 0f;
    }
}

