public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static bool Near(float a, float b) { return System.Math.Abs(a - b) <= 1e-4f; }

    static string Chk(PredictedPlayer p, float sim, float render, int pending, string when)
    {
        if (!Near(p.SimX, sim)) return when + ": SimX 기대 " + sim + " / 결과 " + p.SimX;
        if (!Near(p.RenderX, render)) return when + ": RenderX 기대 " + render + " / 결과 " + p.RenderX;
        if (p.PendingCount != pending) return when + ": PendingCount 기대 " + pending + " / 결과 " + p.PendingCount;
        return null;
    }

    static uint _lcg;
    static uint Next(uint mod) { _lcg = unchecked(_lcg * 1664525u + 1013904223u); return (_lcg >> 8) % mod; }

    public static void Main()
    {
        Run("predict-then-ack-discards-input", () =>
        {
            var p = new PredictedPlayer(0f);
            InputCmd c = p.ApplyInput(1, 0.25f);
            if (c.Seq != 1 || c.Dir != 1 || c.Dt != 0.25f) return "첫 ApplyInput 반환 기대 (Seq 1, Dir 1, Dt 0.25) / 결과 (Seq " + c.Seq + ", Dir " + c.Dir + ", Dt " + c.Dt + ")";
            string e = Chk(p, 2f, 2f, 1, "ApplyInput(1, 0.25) 직후");
            if (e != null) return e;
            p.OnServerState(1, 2f);
            e = Chk(p, 2f, 2f, 0, "서버 상태 (Seq 1, X 2) 수신 뒤");
            if (e != null) return e;
            p.ApplyInput(1, 0.125f); p.ApplyInput(0, 0.125f); p.ApplyInput(-1, 0.125f);
            p.OnServerState(3, 3f);
            return Chk(p, 2f, 2f, 1, "입력 2·3·4 뒤 서버 상태 (Seq 3, X 3) 수신");
        });

        Run("replay-uses-each-inputs-own-dt", () =>
        {
            var p = new PredictedPlayer(0f);
            p.ApplyInput(1, 0.5f); p.ApplyInput(1, 0.25f); p.ApplyInput(1, 0.125f);     // 4, 6, 7
            p.OnServerState(1, 4f);
            string e = Chk(p, 7f, 7f, 2, "dt 0.5, 0.25, 0.125 입력 뒤 서버 상태 (Seq 1, X 4) 수신");
            if (e != null) return e;
            p.ApplyInput(-1, 0.5f);                                                       // 3
            p.OnServerState(2, 6f);
            return Chk(p, 3f, 3f, 2, "dt 0.5 의 반대 방향 입력 뒤 서버 상태 (Seq 2, X 6) 수신");
        });

