            DelayedLink<MoveInput> up; DelayedLink<ServerState> down;
            var c = Solo(500, out up, out down);
            c.Tick(0, 1); c.Tick(1, 1); c.Tick(2, 1);                 // 예측 530, 대기 1·2·3
