problems.solutionCode:
using System;

public enum PollResult
{
    None,      // 아직 내보낼 시각이 아니다
    Frame,     // 프레임을 내보냈다
    Missing    // 내보낼 시각이 됐는데 그 프레임이 없다(건너뛴다)
}

// 들쭉날쭉하게 도착하는 프레임 패킷을 잠시 붙잡았다가 일정한 박자로 내보낸다.
// 시각은 모두 호출자가 넘기는 정수 밀리초다.
public sealed class JitterBuffer
{
    public const int Capacity = 64;           // 다음에 내보낼 프레임부터 64개까지만 보관한다
    public const int JitterMultiplier = 3;    // 목표 지연 = 지터 추정값 × 3 (을 [min, max] 로 자른 값)
    public const int MaxStepMs = 2;           // 프레임 하나를 내보낼 때마다 지연을 최대 2ms 만 바꾼다

    private readonly int _frameIntervalMs;
    private readonly int _minDelayMs;
    private readonly int _maxDelayMs;

    private readonly int[] _payload = new int[Capacity];
    private readonly bool[] _present = new bool[Capacity];

    private bool _started;
    private int _nextFrame;          // 다음에 내보낼 프레임 번호
    private long _nextPlayoutMs;     // 그 프레임을 내보낼 시각
    private long _prevTransitMs;     // 직전 패킷의 상대 전송 시간
    private int _jitterQ4;           // 지터 추정값 × 16 (RFC 3550 A.8 의 정수 버전)

    public JitterBuffer(int frameIntervalMs, int minDelayMs, int maxDelayMs)
    {
        _frameIntervalMs = frameIntervalMs;
        _minDelayMs = minDelayMs;
        _maxDelayMs = maxDelayMs;
        CurrentDelayMs = minDelayMs;
    }

    public int JitterMs => _jitterQ4 >> 4;
    public int TargetDelayMs => Math.Clamp(JitterMultiplier * JitterMs, _minDelayMs, _maxDelayMs);
    public int CurrentDelayMs { get; private set; }
    public int LateCount { get; private set; }

    public bool Push(int frame, long nowMs, int payload)
    {
        if (!_started)
        {
            _started = true;
            _nextFrame = frame;
            _nextPlayoutMs = nowMs + CurrentDelayMs;
            _prevTransitMs = Transit(frame, nowMs);
            Store(frame, payload);
            return true;
        }

        if (frame < _nextFrame)
        {
            // 이미 내보냈거나 건너뛴 자리다. 버리지만, 늦었다는 사실은 지터의 증거이므로 추정에 반영한다.
            LateCount++;
            ObserveTransit(frame, nowMs);
            return false;
        }

        if (frame - _nextFrame >= Capacity) return false;      // 창 밖(너무 먼 미래)
        if (_present[frame % Capacity]) return false;           // 버퍼에 이미 있는 중복

        ObserveTransit(frame, nowMs);
        Store(frame, payload);
        return true;
    }

    public PollResult Poll(long nowMs, out int frame, out int payload)
    {
        frame = 0;
        payload = 0;
        if (!_started || nowMs < _nextPlayoutMs) return PollResult.None;

        frame = _nextFrame;
        int slot = frame % Capacity;
        PollResult result;
        if (_present[slot])
        {
            payload = _payload[slot];
            _present[slot] = false;
            result = PollResult.Frame;
        }
        else
        {
            result = PollResult.Missing;
        }

        // 다음 프레임으로 넘어가면서 지연을 목표 쪽으로 조금만(±MaxStepMs) 옮긴다.
        _nextFrame++;
        int step = Math.Clamp(TargetDelayMs - CurrentDelayMs, -MaxStepMs, MaxStepMs);
        CurrentDelayMs += step;
        _nextPlayoutMs += _frameIntervalMs + step;
        return result;
    }

    // 상대 전송 시간: 도착 시각 - 송신 시각. 송신자는 frame 번을 frame × 간격 시각에 보낸다고 본다.
    // 두 기기의 시계 차이는 상수로 들어가지만, 쓰는 것은 연속한 두 값의 차이뿐이라 상쇄된다.
    private long Transit(int frame, long nowMs) => nowMs - (long)frame * _frameIntervalMs;

    // RFC 3550 6.4.1 / A.8: J = J + (|D| - J) / 16 을 16배로 확대한 정수로 유지한다.
    private void ObserveTransit(int frame, long nowMs)
    {
        long transit = Transit(frame, nowMs);
        long d = transit - _prevTransitMs;
        _prevTransitMs = transit;
        if (d < 0) d = -d;
        _jitterQ4 += (int)d - ((_jitterQ4 + 8) >> 4);
    }

    private void Store(int frame, int payload)
    {
        int slot = frame % Capacity;
        _payload[slot] = payload;
        _present[slot] = true;
    }
}

