            if (c.TargetDelayMs != 200) return "지터가 아주 큰 흐름: TargetDelayMs 는 maxDelayMs(200) 로 잘려야 함 / 결과 " + c.TargetDelayMs;
            if (c.CurrentDelayMs != 10) return "아직 프레임을 하나도 내보내지 않았으므로 CurrentDelayMs 는 처음 값 10 / 결과 " + c.CurrentDelayMs;
            return null;
        });

        Run("delay-adapts-in-small-steps", () =>
        {
            var b = new JitterBuffer(20, 40, 120);
            // 0 ~ 199번: 홀수 프레임만 60ms 늦게 도착(지터 큼). 200 ~ 699번: 제때 도착(지터 없음).
            long lastEvent = -1; int prevDelay = 40, events = 0, delayAt199 = -1, lateMissing = 0;
            for (long t = 1000; t <= 1000 + 20 * 700 + 200; t++)
            {
                long k = t - 1000;
                if (k % 20 == 0 && k / 20 < 700 && ((k / 20) % 2 == 0 || k / 20 >= 200)) b.Push((int)(k / 20), t, 1);
                long k2 = k - 60;
                if (k2 >= 0 && k2 % 20 == 0 && k2 / 20 < 200 && (k2 / 20) % 2 == 1) b.Push((int)(k2 / 20), t, 1);
                int f, p; PollResult r;
                while ((r = b.Poll(t, out f, out p)) != PollResult.None)
                {
                    events++;
                    if (lastEvent >= 0 && (t - lastEvent < 18 || t - lastEvent > 22)) return f + "번 프레임: 직전 방출과의 간격 " + (t - lastEvent) + "ms (20 ± 2 여야 함)";
                    lastEvent = t;
                    int d = b.CurrentDelayMs;
                    if (d < 40 || d > 120) return f + "번 프레임 뒤 CurrentDelayMs " + d + " (40 ~ 120 이어야 함)";
                    if (System.Math.Abs(d - prevDelay) > 2) return f + "번 프레임 뒤 CurrentDelayMs 가 한 번에 " + prevDelay + " → " + d + " 로 바뀜(최대 2ms)";
                    prevDelay = d;
                    if (f == 199) delayAt199 = d;
                    if (f >= 150 && f < 200 && r == PollResult.Missing) lateMissing++;
                }
            }
            if (delayAt199 != 120) return "지터가 큰 구간의 끝(199번 프레임)에서 CurrentDelayMs 기대 120 / 결과 " + delayAt199;
            if (lateMissing != 0) return "지연이 충분히 늘어난 뒤(150 ~ 199번)에도 Missing 이 " + lateMissing + "번 나옴";
            if (b.CurrentDelayMs != 40 || b.JitterMs != 0) return "지터가 사라진 뒤 CurrentDelayMs 40, JitterMs 0 기대 / 결과 " + b.CurrentDelayMs + ", " + b.JitterMs;
            if (events < 700) return "방출 이벤트 수 " + events + " (700 이상이어야 함)";
            return null;
        });

        Run("late-poll-catches-up", () =>
        {
            var b = new JitterBuffer(20, 40, 120);
            for (int f = 0; f < 4; f++) b.Push(f, 1000 + 20 * f, f * 10);
            // 호출자가 1125ms 까지 Poll 을 못 불렀다: 밀린 프레임을 한 번에 하나씩 순서대로 내준다.
            return Want(b, 1125, "F0:0") ?? Want(b, 1125, "F1:10") ?? Want(b, 1125, "F2:20") ?? Want(b, 1125, "F3:30") ?? Want(b, 1125, "M4") ?? Want(b, 1125, "-")
                ?? Push(b, 4, 1126, false) ?? Push(b, 5, 1127, true) ?? Want(b, 1139, "-") ?? Want(b, 1140, "F5:50");
        });

        Run("random-trace-vs-reference", () =>
        {
            _lcg = 3550u;
            for (int run = 0; run < 25; run++)
            {
                int iv = new[] { 10, 20, 33 }[run % 3], min = 10 + (int)Next(40), max = min + 20 + (int)Next(150);
                var b = new JitterBuffer(iv, min, max); var r = new Ref(iv, min, max);
                var arr = new System.Collections.Generic.List<long[]>();           // { 도착 시각, 프레임, 생성 순서 }
                int first = (int)Next(500);
                for (int f = 0; f < 400; f++)
                {
                    int amp = (f / 80) % 3 == 0 ? 6 : ((f / 80) % 3 == 1 ? 45 : 160);
                    long at = 2000 + (long)f * iv + Next((uint)amp);
                    if (Next(10) != 0) arr.Add(new long[] { at, first + f, arr.Count });
                    if (Next(10) == 0) arr.Add(new long[] { at + Next(60), first + f, arr.Count });      // 중복
                    if (Next(60) == 0) arr.Add(new long[] { at, first + f + 64 + Next(40), arr.Count });   // 창 밖
                }
                arr.Sort((x, y) => x[0] != y[0] ? x[0].CompareTo(y[0]) : x[2].CompareTo(y[2]));
                int ai = 0; long end = arr[arr.Count - 1][0] + 300;
                for (long t = 2000; t <= end; t++)
                {
                    while (ai < arr.Count && arr[ai][0] == t)
                    {
                        int f = (int)arr[ai][1]; ai++;
                        bool want = r.Push(f, t, f * 3), got = b.Push(f, t, f * 3);
                        if (want != got) return run + "회차 " + t + "ms: Push(frame " + f + ") 기대 " + want + " / 결과 " + got;
                    }
                    if (Next(3) == 0)
                    {
                        while (true)
                        {
                            string want = r.Poll(t), got = Ev(b, t);
                            if (want != got) return run + "회차 " + t + "ms: Poll 기대 " + want + " / 결과 " + got;
                            if (want == "-") break;
                        }
                    }
                    if (b.JitterMs != r.Jit || b.TargetDelayMs != r.Target || b.CurrentDelayMs != r.Cur || b.LateCount != r.Late)
                        return run + "회차 " + t + "ms: 기대 JitterMs " + r.Jit + ", TargetDelayMs " + r.Target + ", CurrentDelayMs " + r.Cur + ", LateCount " + r.Late
                            + " / 결과 " + b.JitterMs + ", " + b.TargetDelayMs + ", " + b.CurrentDelayMs + ", " + b.LateCount;
                }
            }
            return null;
        });
    }
}

