using System;
using System.Buffers.Binary;

// 서버가 매 틱 보내는 엔티티 하나의 상태(이미 양자화된 정수 값).
public struct EntityState : IEquatable<EntityState>
{
    public short X;
    public short Z;
    public byte Hp;

    public EntityState(short x, short z, byte hp) { X = x; Z = z; Hp = hp; }
    public bool Equals(EntityState o) => X == o.X && Z == o.Z && Hp == o.Hp;
    public override bool Equals(object obj) => obj is EntityState o && Equals(o);
    public override int GetHashCode() => HashCode.Combine(X, Z, Hp);
    public override string ToString() => "(" + X + ", " + Z + ", " + Hp + ")";
}

// 패킷 형식(리틀 엔디언). 송신·수신이 똑같이 지켜야 한다.
//   [0..3]  int32 sequence   이 스냅샷의 번호(0, 1, 2, ...)
//   [4..7]  int32 baseline   기준 스냅샷 번호, -1 이면 "모든 엔티티가 default 인 초기 상태"
//   [8.. ]  변경 비트맵 BitmapSize(n) 바이트: 엔티티 i 가 기준과 다르면 바이트 i / 8 의 비트 i % 8 이 1
//   이어서 바뀐 엔티티마다(번호 오름차순): 필드 마스크 1바이트(bit0 X, bit1 Z, bit2 Hp, 바뀐 필드만 1),
//   그다음 마스크가 켜진 필드만 X(int16), Z(int16), Hp(byte) 순서로.
public static class DeltaFormat
{
    public const int HistorySize = 32;      // 송신·수신 모두 최근 32개 스냅샷을 기억한다
    public const int InitialBaseline = -1;
    public const int HeaderSize = 8;
    public const byte FieldX = 1, FieldZ = 2, FieldHp = 4;

    public static int BitmapSize(int entityCount) => (entityCount + 7) / 8;
    public static int MaxPacketSize(int entityCount) => HeaderSize + BitmapSize(entityCount) + entityCount * 6;
}

public sealed class DeltaSender
{
    private readonly int _count;
    private readonly EntityState[][] _history = new EntityState[DeltaFormat.HistorySize][];
    private readonly int[] _historySeq = new int[DeltaFormat.HistorySize];
    private int _acked = -1;                 // 받았다고 확인된 가장 새로운 번호(-1 = 없음)

    public DeltaSender(int entityCount)
    {
        _count = entityCount;
        for (int i = 0; i < DeltaFormat.HistorySize; i++) { _history[i] = new EntityState[entityCount]; _historySeq[i] = -1; }
    }

    // 음수를 % 하면 음수 나머지가 나오므로 먼저 걸러 낸다.
    private bool InHistory(int seq) => seq >= 0 && _historySeq[seq % DeltaFormat.HistorySize] == seq;

    public void OnAck(int sequence)
    {
        // 보낸 적이 없거나 이미 기록에서 밀려난 번호, 지금 기준보다 오래된 확인은 무시한다.
        if (InHistory(sequence) && sequence > _acked) _acked = sequence;
    }

    public int Encode(int sequence, EntityState[] states, byte[] buffer)
    {
        // 1) 기준 고르기: 확인된 가장 새로운 스냅샷이 아직 기록에 있으면 그것, 아니면 초기 상태.
        //    (새 스냅샷을 기록하기 전에 고른다. 그래야 sequence - 32 도 기준으로 쓸 수 있다.)
        int baseline = InHistory(_acked) ? _acked : DeltaFormat.InitialBaseline;
        EntityState[] baseStates = baseline == DeltaFormat.InitialBaseline ? null : _history[baseline % DeltaFormat.HistorySize];

        BinaryPrimitives.WriteInt32LittleEndian(buffer.AsSpan(0, 4), sequence);
        BinaryPrimitives.WriteInt32LittleEndian(buffer.AsSpan(4, 4), baseline);
        int bitmapAt = DeltaFormat.HeaderSize;
        int bitmapSize = DeltaFormat.BitmapSize(_count);
        Array.Clear(buffer, bitmapAt, bitmapSize);                  // 버퍼에는 이전 패킷의 찌꺼기가 있을 수 있다
        int pos = bitmapAt + bitmapSize;

        // 2) 기준과 다른 엔티티만, 그 안에서도 바뀐 필드만 쓴다.
        for (int i = 0; i < _count; i++)
        {
            EntityState b = baseStates == null ? default : baseStates[i];
            EntityState s = states[i];
            byte mask = 0;
            if (s.X != b.X) mask |= DeltaFormat.FieldX;
            if (s.Z != b.Z) mask |= DeltaFormat.FieldZ;
            if (s.Hp != b.Hp) mask |= DeltaFormat.FieldHp;
            if (mask == 0) continue;

            buffer[bitmapAt + i / 8] |= (byte)(1 << (i % 8));
            buffer[pos++] = mask;
            if ((mask & DeltaFormat.FieldX) != 0) { BinaryPrimitives.WriteInt16LittleEndian(buffer.AsSpan(pos, 2), s.X); pos += 2; }
            if ((mask & DeltaFormat.FieldZ) != 0) { BinaryPrimitives.WriteInt16LittleEndian(buffer.AsSpan(pos, 2), s.Z); pos += 2; }
            if ((mask & DeltaFormat.FieldHp) != 0) buffer[pos++] = s.Hp;
        }

        // 3) 보낸 스냅샷을 "복사해서" 기록한다. 호출자는 states 배열을 다음 틱에 다시 쓴다.
        int slot = sequence % DeltaFormat.HistorySize;
        Array.Copy(states, _history[slot], _count);
        _historySeq[slot] = sequence;
        return pos;
    }
}

public sealed class DeltaReceiver
{
    private readonly int _count;
    private readonly EntityState[][] _history = new EntityState[DeltaFormat.HistorySize][];
    private readonly int[] _historySeq = new int[DeltaFormat.HistorySize];
    private readonly EntityState[] _work;     // 끝까지 읽기 전에는 output 과 기록을 건드리지 않는다

    public DeltaReceiver(int entityCount)
    {
        _count = entityCount;
        _work = new EntityState[entityCount];
        for (int i = 0; i < DeltaFormat.HistorySize; i++) { _history[i] = new EntityState[entityCount]; _historySeq[i] = -1; }
    }

    public bool TryDecode(byte[] packet, int length, EntityState[] output, out int sequence)
    {
        sequence = -1;
        int bitmapAt = DeltaFormat.HeaderSize;
        int pos = bitmapAt + DeltaFormat.BitmapSize(_count);
        if (length < pos) return false;

        int seq = BinaryPrimitives.ReadInt32LittleEndian(packet.AsSpan(0, 4));
        int baseline = BinaryPrimitives.ReadInt32LittleEndian(packet.AsSpan(4, 4));
        if (seq < 0) return false;

        // 기준 찾기: 초기 상태이거나, 그 번호가 정확히 기록에 있어야 한다(칸의 번호까지 확인).
        if (baseline == DeltaFormat.InitialBaseline) Array.Clear(_work, 0, _count);
        else if (baseline >= 0 && _historySeq[baseline % DeltaFormat.HistorySize] == baseline)
            Array.Copy(_history[baseline % DeltaFormat.HistorySize], _work, _count);
        else return false;                                               // 기준이 없다: 추측해서 풀지 않는다

        for (int i = 0; i < _count; i++)
        {
            if ((packet[bitmapAt + i / 8] & (1 << (i % 8))) == 0) continue;
            if (pos + 1 > length) return false;
            byte mask = packet[pos++];
            if ((mask & DeltaFormat.FieldX) != 0)
            {
                if (pos + 2 > length) return false;
                _work[i].X = BinaryPrimitives.ReadInt16LittleEndian(packet.AsSpan(pos, 2)); pos += 2;
            }
            if ((mask & DeltaFormat.FieldZ) != 0)
            {
                if (pos + 2 > length) return false;
                _work[i].Z = BinaryPrimitives.ReadInt16LittleEndian(packet.AsSpan(pos, 2)); pos += 2;
            }
            if ((mask & DeltaFormat.FieldHp) != 0)
            {
                if (pos + 1 > length) return false;
                _work[i].Hp = packet[pos++];
            }
        }

        // 다 읽은 뒤에만 결과를 내보내고 기록한다. 늦게 온 옛 스냅샷이 더 새로운 기록을 밀어내지 않게 한다.
        Array.Copy(_work, output, _count);
        int slot = seq % DeltaFormat.HistorySize;
        if (_historySeq[slot] < seq)
        {
            Array.Copy(_work, _history[slot], _count);
            _historySeq[slot] = seq;
        }
        sequence = seq;
        return true;
    }
}

