public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static EntityState E(int x, int z, int hp) => new EntityState((short)x, (short)z, (byte)hp);
    static string Hex(byte[] b, int n) { var s = new System.Text.StringBuilder(); for (int i = 0; i < n; i++) s.Append(b[i].ToString("X2")).Append(i + 1 < n ? " " : ""); return s.ToString(); }
    static byte[] Garbage(int n) { var b = new byte[n]; for (int i = 0; i < n; i++) b[i] = 0xCD; return b; }
    static int Base(byte[] p) => System.BitConverter.ToInt32(p, 4);   // 시험 기기는 리틀 엔디언

    // 송신 측: 인코딩 결과를 기대 바이트열과 비교한다
    static string Enc(DeltaSender s, int seq, EntityState[] st, string want)
    {
        byte[] buf = Garbage(DeltaFormat.MaxPacketSize(st.Length) + 8);
        int n = s.Encode(seq, st, buf);
        string got = Hex(buf, n);
        return got == want ? null : "스냅샷 " + seq + " 인코딩 기대 [" + want + "] / 결과 [" + got + "]";
    }

    // ---- 기준 구현(형식과 기준 선택 규칙 그대로) ----
    sealed class Ref
    {
        readonly int n; readonly EntityState[][] h = new EntityState[32][]; readonly int[] hs = new int[32]; int acked = -1;
        public Ref(int count) { n = count; for (int i = 0; i < 32; i++) { h[i] = new EntityState[n]; hs[i] = -1; } }
        bool Has(int q) => q >= 0 && hs[q % 32] == q;
        public void Ack(int q) { if (Has(q) && q > acked) acked = q; }
        public byte[] Encode(int seq, EntityState[] st)
        {
            int b = Has(acked) ? acked : -1, bm = (n + 7) / 8, pos = 8 + bm;
            var buf = new byte[8 + bm + n * 6];
            System.BitConverter.GetBytes(seq).CopyTo(buf, 0); System.BitConverter.GetBytes(b).CopyTo(buf, 4);
            for (int i = 0; i < n; i++)
            {
                EntityState o = b < 0 ? default : h[b % 32][i], c = st[i];
                int m = (c.X != o.X ? 1 : 0) | (c.Z != o.Z ? 2 : 0) | (c.Hp != o.Hp ? 4 : 0);
                if (m == 0) continue;
                buf[8 + i / 8] |= (byte)(1 << (i % 8)); buf[pos++] = (byte)m;
                if ((m & 1) != 0) { System.BitConverter.GetBytes(c.X).CopyTo(buf, pos); pos += 2; }
                if ((m & 2) != 0) { System.BitConverter.GetBytes(c.Z).CopyTo(buf, pos); pos += 2; }
                if ((m & 4) != 0) buf[pos++] = c.Hp;
            }
            System.Array.Copy(st, h[seq % 32], n); hs[seq % 32] = seq;
            System.Array.Resize(ref buf, pos); return buf;
        }
        public bool Decode(byte[] p, int len, EntityState[] outp, out int seq)
        {
            seq = -1; int bm = (n + 7) / 8, pos = 8 + bm;
            if (len < pos) return false;
            int q = System.BitConverter.ToInt32(p, 0), b = System.BitConverter.ToInt32(p, 4);
            if (q < 0 || (b != -1 && !Has(b))) return false;
            var w = new EntityState[n]; if (b >= 0) System.Array.Copy(h[b % 32], w, n);
            for (int i = 0; i < n; i++)
            {
                if ((p[8 + i / 8] & (1 << (i % 8))) == 0) continue;
                if (pos >= len) return false; int m = p[pos++];
                if ((m & 1) != 0) { if (pos + 2 > len) return false; w[i].X = System.BitConverter.ToInt16(p, pos); pos += 2; }
                if ((m & 2) != 0) { if (pos + 2 > len) return false; w[i].Z = System.BitConverter.ToInt16(p, pos); pos += 2; }
                if ((m & 4) != 0) { if (pos + 1 > len) return false; w[i].Hp = p[pos++]; }
            }
            System.Array.Copy(w, outp, n); if (hs[q % 32] < q) { System.Array.Copy(w, h[q % 32], n); hs[q % 32] = q; }
            seq = q; return true;
        }
    }

    // 받는 쪽: 기대 결과(want = null 이면 false 기대)와 비교하고, 실패할 때 output 이 그대로인지 본다
    static string Dec(DeltaReceiver r, byte[] p, int len, EntityState[] want, string what)
    {
        var outp = new EntityState[want == null ? 4 : want.Length];
        for (int i = 0; i < outp.Length; i++) outp[i] = E(-77, -77, 77);
        bool ok = r.TryDecode(p, len, outp, out int seq);
        if (want == null)
        {
            if (ok) return what + ": false 기대 / 결과 true";
            for (int i = 0; i < outp.Length; i++) if (!outp[i].Equals(E(-77, -77, 77))) return what + ": false 를 반환했는데 output[" + i + "] 이 바뀜";
            return null;
        }
        if (!ok) return what + ": true 기대 / 결과 false";
        if (seq != System.BitConverter.ToInt32(p, 0)) return what + ": sequence 기대 " + System.BitConverter.ToInt32(p, 0) + " / 결과 " + seq;
        for (int i = 0; i < want.Length; i++) if (!outp[i].Equals(want[i])) return what + ": 엔티티 " + i + " 기대 " + want[i] + " / 결과 " + outp[i];
        return null;
    }

    static EntityState[] Snap(int seq, int n) { var a = new EntityState[n]; for (int i = 0; i < n; i++) a[i] = E(seq * 3 + i, i - seq, (seq + i) % 200); return a; }

    static uint _lcg;
    static uint Next(uint mod) { _lcg = unchecked(_lcg * 1664525u + 1013904223u); return (_lcg >> 8) % mod; }

    public static void Main()
    {
        Run("encode-exact-bytes", () =>
        {
            var s = new DeltaSender(3);
            string e = Enc(s, 0, new[] { E(10, -2, 100), E(0, 0, 0), E(300, 5, 7) }, "00 00 00 00 FF FF FF FF 05 07 0A 00 FE FF 64 07 2C 01 05 00 07")
                ?? Enc(s, 1, new[] { E(11, -2, 100), E(0, 0, 0), E(300, 5, 7) }, "01 00 00 00 FF FF FF FF 05 07 0B 00 FE FF 64 07 2C 01 05 00 07");
            if (e != null) return "(확인 없음) " + e;
            s.OnAck(1);
            return Enc(s, 2, new[] { E(11, -2, 100), E(0, 0, 0), E(300, 5, 7) }, "02 00 00 00 01 00 00 00 00")
                ?? Enc(s, 3, new[] { E(11, -2, 100), E(0, 0, 9), E(300, -1, 7) }, "03 00 00 00 01 00 00 00 06 04 09 02 FF FF")
                ?? Enc(s, 4, new[] { E(11, -2, 100), E(0, 0, 9), E(300, -1, 7) }, "04 00 00 00 01 00 00 00 06 04 09 02 FF FF");
        });

        Run("ack-selection", () =>
        {
            var s = new DeltaSender(5); var buf = new byte[DeltaFormat.MaxPacketSize(5)];
            for (int q = 0; q < 10; q++) s.Encode(q, Snap(q, 5), buf);
            s.OnAck(3); s.OnAck(7); s.OnAck(5); s.OnAck(7); s.OnAck(99); s.OnAck(10); s.OnAck(-3); s.OnAck(int.MinValue);
            s.Encode(10, Snap(10, 5), buf);
            if (Base(buf) != 7) return "확인 3, 7, 5, 7, 99, 10, -3 뒤 스냅샷 10 의 기준 기대 7 / 결과 " + Base(buf);
            s.OnAck(8); s.OnAck(6);
            s.Encode(11, Snap(11, 5), buf);
            return Base(buf) == 8 ? null : "이어서 확인 8, 6 뒤 스냅샷 11 의 기준 기대 8 / 결과 " + Base(buf);
        });

        Run("baseline-window-edge", () =>
        {
            var s = new DeltaSender(4); var buf = new byte[DeltaFormat.MaxPacketSize(4)];
            s.Encode(0, Snap(0, 4), buf); s.OnAck(0);
            for (int q = 1; q <= 33; q++)
            {
                s.Encode(q, Snap(q, 4), buf);
                int want = q <= 32 ? 0 : -1;
                if (Base(buf) != want) return "0 만 확인된 채 스냅샷 " + q + " 의 기준 기대 " + want + " / 결과 " + Base(buf) + " (기준이 될 수 있는 번호는 sequence - 32 이상)";
            }
            s.OnAck(1); s.Encode(34, Snap(34, 4), buf);
            if (Base(buf) != -1) return "기록에서 밀려난 1 을 확인한 뒤 스냅샷 34 의 기준 기대 -1 / 결과 " + Base(buf);
            s.OnAck(33); s.Encode(35, Snap(35, 4), buf);
            return Base(buf) == 33 ? null : "33 을 확인한 뒤 스냅샷 35 의 기준 기대 33 / 결과 " + Base(buf);
        });

        Run("decode-roundtrip", () =>
        {
            var rs = new Ref(3); var r = new DeltaReceiver(3);
            var a = new[] { E(10, -2, 100), E(0, 0, 0), E(300, 5, 7) }; var b = new[] { E(11, -2, 100), E(0, 0, 9), E(-300, -1, 7) };
            var p0 = rs.Encode(0, a); rs.Ack(0); var p1 = rs.Encode(1, b); rs.Ack(1); var p2 = rs.Encode(2, b);
            return Dec(r, p0, p0.Length, a, "초기 상태 기준 스냅샷 0") ?? Dec(r, p1, p1.Length, b, "0 기준 스냅샷 1") ?? Dec(r, p2, p2.Length, b, "1 기준, 바뀐 것 없는 스냅샷 2")
                ?? Dec(r, p1, p1.Length, b, "중복으로 다시 온 스냅샷 1");
        });

        Run("decode-missing-baseline", () =>
        {
            var rs = new Ref(4); var r = new DeltaReceiver(4); var lost = new System.Collections.Generic.List<byte[]>();
            for (int q = 0; q <= 40; q++) { var p = rs.Encode(q, Snap(q, 4)); if (q == 5) { rs.Ack(5); lost.Add(p); } else if (q > 5) { lost.Add(p); } else if (Dec(r, p, p.Length, Snap(q, 4), "스냅샷 " + q) is string e) return e; }
            // 클라이언트는 5 이후를 하나도 받지 못했다. 6 ~ 36 은 5 기준이므로 풀 수 없어야 한다.
            if (Dec(r, lost[1], lost[1].Length, null, "받지 못한 5 를 기준으로 한 스냅샷 6") is string e2) return e2;
            var bad = (byte[])lost[1].Clone(); System.BitConverter.GetBytes(-7).CopyTo(bad, 4);
            if (Dec(r, bad, bad.Length, null, "기준 번호가 -7 인 패킷") is string e3) return e3;
            System.BitConverter.GetBytes(int.MinValue).CopyTo(bad, 4);
            if (Dec(r, bad, bad.Length, null, "기준 번호가 int.MinValue 인 패킷") is string e4) return e4;
            System.BitConverter.GetBytes(-5).CopyTo(bad, 0); System.BitConverter.GetBytes(-1).CopyTo(bad, 4);
            if (Dec(r, bad, bad.Length, null, "번호가 -5 인 패킷") is string e5) return e5;
            return Dec(r, lost[0], lost[0].Length, Snap(5, 4), "늦게 온 스냅샷 5") ?? Dec(r, lost[1], lost[1].Length, Snap(6, 4), "5 를 받은 뒤의 스냅샷 6");
        });

        Run("decode-malformed-atomic", () =>
        {
            var rs = new Ref(4); var r = new DeltaReceiver(4);
            var p0 = rs.Encode(0, Snap(0, 4)); rs.Ack(0); var p1 = rs.Encode(1, Snap(1, 4)); rs.Ack(1); var p2 = rs.Encode(2, Snap(2, 4));
            if (Dec(r, p0, p0.Length, Snap(0, 4), "스냅샷 0") is string e0) return e0;
            var big = Garbage(64); p1.CopyTo(big, 0);
            for (int len = 0; len < p1.Length; len++)
                if (Dec(r, big, len, null, "앞 " + len + "바이트만 온 스냅샷 1 (전체 " + p1.Length + "바이트)") is string e) return e;
            // 잘린 1 이 기록에 남았다면 1 기준인 스냅샷 2 를 풀어 버린다
            return Dec(r, p2, p2.Length, null, "끝내 온전히 받지 못한 1 을 기준으로 한 스냅샷 2") ?? Dec(r, big, p1.Length, Snap(1, 4), "온전한 스냅샷 1(뒤에 쓰레기 바이트)")
                ?? Dec(r, p2, p2.Length, Snap(2, 4), "1 을 받은 뒤의 스냅샷 2");
        });

        Run("decode-keeps-newer-history", () =>
        {
            var rs = new Ref(4); var r = new DeltaReceiver(4); byte[] late = null; byte[] p = null;
            for (int q = 0; q <= 35; q++) { p = rs.Encode(q, Snap(q, 4)); if (q == 3) { late = p; continue; } if (Dec(r, p, p.Length, Snap(q, 4), "스냅샷 " + q) is string e) return e; if (q >= 34) rs.Ack(q); }
            var p36 = rs.Encode(36, Snap(36, 4));   // 35 기준
            return Dec(r, late, late.Length, Snap(3, 4), "33틱 늦게 온 초기 상태 기준 스냅샷 3") ?? Dec(r, p36, p36.Length, Snap(36, 4), "그 뒤 35 기준 스냅샷 36 (같은 칸의 35 를 3 이 덮어쓰면 실패)");
        });

        Run("lossy-link-sim", () =>
        {
            const int N = 40, T = 700; _lcg = 2024u;
            var refS = new Ref(N); var refR = new Ref(N); var s = new DeltaSender(N); var r = new DeltaReceiver(N);
            var truth = new EntityState[T][]; var cur = new EntityState[N]; var buf = Garbage(DeltaFormat.MaxPacketSize(N));
            var toClient = new System.Collections.Generic.List<(int at, byte[] p)>(); var toServer = new System.Collections.Generic.List<(int at, int seq)>();
            var outL = new EntityState[N]; var outR = new EntityState[N]; var inbox = Garbage(DeltaFormat.MaxPacketSize(N) + 16);
            for (int t = 0; t < T; t++)
            {
                foreach (var a in toServer.FindAll(x => x.at == t)) { s.OnAck(a.seq); refS.Ack(a.seq); }
                for (int i = 0; i < N; i++) { if (Next(8) == 0) cur[i].X += (short)(Next(7) - 3); if (Next(9) == 0) cur[i].Z -= (short)Next(4); if (Next(60) == 0) cur[i].Hp = (byte)Next(256); }
                truth[t] = (EntityState[])cur.Clone();
                int n = s.Encode(t, cur, buf); var want = refS.Encode(t, cur);
                if (Hex(buf, n) != Hex(want, want.Length))
                {
                    int k = 0; while (k < n && k < want.Length && buf[k] == want[k]) k++;
                    return "틱 " + t + " 송신 패킷이 규칙과 다름: 기대 기준 " + Base(want) + ", 길이 " + want.Length + " / 결과 기준 " + Base(buf) + ", 길이 " + n + " (처음 다른 바이트 위치 " + k + ")";
                }
                if (Next(100) >= 10) toClient.Add((t + 1 + (int)Next(4), want));
                if (Next(100) < 6) toClient.Add((t + 1 + (int)Next(45), want));   // 중복, 아주 늦게 올 수도 있다
                var arrived = toClient.FindAll(x => x.at == t); arrived.Reverse();
                foreach (var (at, p) in arrived)
                {
                    p.CopyTo(inbox, 0);
                    bool okL = r.TryDecode(inbox, p.Length, outL, out int qL), okR = refR.Decode(p, p.Length, outR, out int qR);
                    if (okL != okR) return "틱 " + t + " 에 도착한 스냅샷 " + System.BitConverter.ToInt32(p, 0) + "(기준 " + Base(p) + ") TryDecode 기대 " + (okR ? "true" : "false") + " / 결과 " + (okL ? "true" : "false");
                    if (!okR) continue;
                    for (int i = 0; i < N; i++) if (!outL[i].Equals(truth[qR][i])) return "스냅샷 " + qR + " 엔티티 " + i + " 기대 " + truth[qR][i] + " / 결과 " + outL[i];
                    if ((t < 200 || t > 260) && Next(100) >= 15) toServer.Add((t + 1 + (int)Next(4), qR));
                }
            }
            return null;
        });
    }
}

