using System;
using System.Collections.Generic;

public enum RoomPhase { Waiting, Countdown, Started }

// 클라이언트가 보내는 "내가 원하는 내 상태" 메시지. 토글이 아니라 절대 상태다.
// Seq 는 클라이언트마다 1 부터 1씩 늘린다(재전송한 중복은 같은 Seq).
public readonly struct PlayerMsg
{
    public readonly int PlayerId;
    public readonly int Seq;
    public readonly bool InRoom;
    public readonly bool Ready;

    public PlayerMsg(int playerId, int seq, bool inRoom, bool ready) { PlayerId = playerId; Seq = seq; InRoom = inRoom; Ready = ready; }
    public static PlayerMsg Join(int player, int seq) => new PlayerMsg(player, seq, true, false);
    public static PlayerMsg SetReady(int player, int seq, bool ready) => new PlayerMsg(player, seq, true, ready);
    public static PlayerMsg Leave(int player, int seq) => new PlayerMsg(player, seq, false, false);
}

public sealed class Lobby
{
    public const int MinPlayers = 2;
    public const int CountdownMs = 3000;

    // 나간 플레이어의 항목도 지우지 않는다(InRoom = false). 마지막으로 적용한 Seq 를 잃으면 늦게 온 옛 메시지를 걸러 낼 수 없다.
    private sealed class PlayerEntry { public int LastSeq; public bool InRoom; public bool Ready; }
    private readonly Dictionary<int, PlayerEntry> _players = new Dictionary<int, PlayerEntry>();

    public RoomPhase Phase { get; private set; } = RoomPhase.Waiting;
    public int StartAtMs { get; private set; } = -1;   // 카운트다운이 끝나 게임이 시작되는 시각

    public bool IsMember(int playerId) => _players.TryGetValue(playerId, out PlayerEntry e) && e.InRoom;
    public bool IsReady(int playerId) => _players.TryGetValue(playerId, out PlayerEntry e) && e.Ready;
    public int MemberCount { get { int n = 0; foreach (PlayerEntry e in _players.Values) if (e.InRoom) n++; return n; } }

    // 호출자 보장: nowMs 는 줄어들지 않는다.
    public void Update(int nowMs)
    {
        if (Phase == RoomPhase.Countdown && nowMs >= StartAtMs) Phase = RoomPhase.Started;
    }

    public void Receive(PlayerMsg m, int nowMs)
    {
        Update(nowMs);
        if (Phase == RoomPhase.Started) return;          // 시작한 뒤의 로비 메시지는 게임 쪽이 처리한다

        // 나가기를 포함한 모든 메시지가 같은 버전 검사를 거친다.
        if (!_players.TryGetValue(m.PlayerId, out PlayerEntry e))
        {
            e = new PlayerEntry();                        // 처음 보는 플레이어(나가기가 먼저 와도 기록만 남긴다)
            _players.Add(m.PlayerId, e);
        }
        if (m.Seq <= e.LastSeq) return;                   // 중복이거나 늦게 온 옛 메시지
        e.LastSeq = m.Seq;
        e.InRoom = m.InRoom;
        e.Ready = m.InRoom && m.Ready;
        Reevaluate(nowMs);
    }

    // 인원이 MinPlayers 이상이고 전원이 준비했으면 카운트다운, 아니면 대기.
    private void Reevaluate(int nowMs)
    {
        int members = 0, ready = 0;
        foreach (PlayerEntry e in _players.Values) { if (!e.InRoom) continue; members++; if (e.Ready) ready++; }
        bool allReady = members >= MinPlayers && ready == members;

        // 전이는 조건이 "바뀔 때"만 일어난다. 이미 카운트다운 중이면 시작 시각을 건드리지 않는다.
        if (allReady && Phase == RoomPhase.Waiting)
        {
            Phase = RoomPhase.Countdown;
            StartAtMs = nowMs + CountdownMs;
        }
        else if (!allReady && Phase == RoomPhase.Countdown)
        {
            Phase = RoomPhase.Waiting;
        }
    }
}

// QA 가 재현한 도착 순서(서버에 도착한 시각 순). 고정 스크립트다.
public readonly struct Arrival
{
    public readonly int AtMs;
    public readonly PlayerMsg Msg;
    public Arrival(int atMs, PlayerMsg msg) { AtMs = atMs; Msg = msg; }
}

public static class LobbyScripts
{
    // 제보 1: 나갔다가 곧바로 다시 들어와 준비한 1번이, 늦게 도착한 옛 "나가기" 때문에 방에서 사라진다.
    public static readonly Arrival[] LateLeaveAfterRejoin =
    {
        new Arrival(0, PlayerMsg.Join(1, 1)),
