    // 제보 3: 클라이언트는 1초마다 현재 상태를 새 Seq 로 다시 보낸다(상태 새로고침). 카운트다운이 끝나지 않는다.
    public static readonly Arrival[] RefreshDuringCountdown =
    {
        new Arrival(0, PlayerMsg.Join(1, 1)),
        new Arrival(0, PlayerMsg.Join(2, 1)),
        new Arrival(100, PlayerMsg.SetReady(1, 2, true)),
        new Arrival(100, PlayerMsg.SetReady(2, 2, true)),
        new Arrival(1100, PlayerMsg.SetReady(1, 3, true)),
        new Arrival(1100, PlayerMsg.SetReady(2, 3, true)),
        new Arrival(1150, PlayerMsg.SetReady(2, 3, true)),  // 재전송된 중복
        new Arrival(2100, PlayerMsg.SetReady(1, 4, true)),
        new Arrival(2100, PlayerMsg.SetReady(2, 4, true)),
        new Arrival(3100, PlayerMsg.SetReady(1, 5, true)),
        new Arrival(3100, PlayerMsg.SetReady(2, 5, true)),
        new Arrival(4100, PlayerMsg.SetReady(1, 6, true)),
        new Arrival(4100, PlayerMsg.SetReady(2, 6, true)),
    };

    // 스크립트를 순서대로 넣고 endMs 에 Update 를 한 번 부른다. 재현용 도우미.
    public static Lobby Play(Arrival[] script, int endMs)
    {
        var lobby = new Lobby();
        foreach (Arrival a in script) lobby.Receive(a.Msg, a.AtMs);
        lobby.Update(endMs);
        return lobby;
    }
}

