public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static PlayerMsg J(int p, int s) => PlayerMsg.Join(p, s);
    static PlayerMsg R(int p, int s, bool r) => PlayerMsg.SetReady(p, s, r);
    static PlayerMsg L(int p, int s) => PlayerMsg.Leave(p, s);
    static string Who(Lobby l) { string s = ""; for (int p = 1; p <= 4; p++) if (l.IsMember(p)) s += p + (l.IsReady(p) ? "R " : "_ "); return "[" + s.Trim() + "]"; }
    static string State(Lobby l) => l.Phase + (l.Phase == RoomPhase.Waiting ? "" : "(시작 " + l.StartAtMs + "ms)") + " " + Who(l);

    // (시각, 메시지) 를 차례로 넣고, 그 시각 이후 상태가 want 와 같은지 본다. want == null 이면 확인하지 않는다.
    static string Feed(Lobby l, string ctx, params (int at, PlayerMsg m, string want)[] steps)
    {
        foreach (var (at, m, want) in steps)
        {
            l.Receive(m, at);
            if (want != null && State(l) != want)
                return ctx + ": " + at + "ms 에 P" + m.PlayerId + " seq " + m.Seq + (m.InRoom ? (m.Ready ? " 준비" : " 입장·준비 해제") : " 나가기") + " 도착 뒤 기대 " + want + " / 결과 " + State(l);
        }
        return null;
    }
    static string At(Lobby l, int now, string want, string ctx) { l.Update(now); return State(l) == want ? null : ctx + ": " + now + "ms 기대 " + want + " / 결과 " + State(l); }

    // ---- 기준 구현 ----
    sealed class Ref
    {
        readonly System.Collections.Generic.Dictionary<int, (int seq, bool inRoom, bool ready)> p = new System.Collections.Generic.Dictionary<int, (int, bool, bool)>();
        public RoomPhase Phase = RoomPhase.Waiting; public int StartAt = -1;
        public void Update(int now) { if (Phase == RoomPhase.Countdown && now >= StartAt) Phase = RoomPhase.Started; }
        public void Receive(PlayerMsg m, int now)
        {
            Update(now); if (Phase == RoomPhase.Started) return;
            if (p.TryGetValue(m.PlayerId, out var e) && m.Seq <= e.seq) return;
            p[m.PlayerId] = (m.Seq, m.InRoom, m.InRoom && m.Ready);
            int n = 0, r = 0; foreach (var v in p.Values) if (v.inRoom) { n++; if (v.ready) r++; }
            bool go = n >= 2 && r == n;
            if (go && Phase == RoomPhase.Waiting) { Phase = RoomPhase.Countdown; StartAt = now + 3000; } else if (!go && Phase == RoomPhase.Countdown) Phase = RoomPhase.Waiting;
        }
        public string State() { string s = ""; for (int k = 1; k <= 4; k++) if (p.TryGetValue(k, out var v) && v.inRoom) s += k + (v.ready ? "R " : "_ "); return Phase + (Phase == RoomPhase.Waiting ? "" : "(시작 " + StartAt + "ms)") + " [" + s.Trim() + "]"; }
    }

    static uint _lcg;
    static int Next(int mod) { _lcg = unchecked(_lcg * 1664525u + 1013904223u); return (int)((_lcg >> 8) % (uint)mod); }

    public static void Main()
    {
        Run("late-leave-after-rejoin", () =>
        {
            var l = new Lobby();
            return Feed(l, "제보 1 스크립트", (0, J(1, 1), null), (0, J(2, 1), null), (100, L(1, 2), "Waiting [2_]"), (150, R(1, 3, true), "Waiting [1R 2_]"),
                    (200, R(2, 2, true), "Countdown(시작 3200ms) [1R 2R]"), (500, L(1, 2), "Countdown(시작 3200ms) [1R 2R]"))
                ?? At(l, 4000, "Started(시작 3200ms) [1R 2R]", "제보 1 스크립트");
        });

