        {
            var l = new Lobby();
            return Feed(l, "제보 2 스크립트", (0, J(1, 1), null), (0, J(2, 1), null), (0, J(3, 1), null), (100, R(3, 2, true), "Waiting [1_ 2_ 3R]"),
                    (200, L(3, 3), "Waiting [1_ 2_]"), (300, R(3, 2, true), "Waiting [1_ 2_]"), (400, R(1, 2, true), "Waiting [1R 2_]"), (400, R(2, 2, true), "Countdown(시작 3400ms) [1R 2R]"))
                ?? At(l, 4000, "Started(시작 3400ms) [1R 2R]", "제보 2 스크립트");
        });

        Run("refresh-during-countdown", () =>
        {
            var l = new Lobby();
            string e = Feed(l, "제보 3 스크립트", (0, J(1, 1), null), (0, J(2, 1), null), (100, R(1, 2, true), null), (100, R(2, 2, true), "Countdown(시작 3100ms) [1R 2R]"),
                (1100, R(1, 3, true), "Countdown(시작 3100ms) [1R 2R]"), (1100, R(2, 3, true), "Countdown(시작 3100ms) [1R 2R]"), (1150, R(2, 3, true), "Countdown(시작 3100ms) [1R 2R]"),
                (2100, R(1, 4, true), "Countdown(시작 3100ms) [1R 2R]"), (2100, R(2, 4, true), "Countdown(시작 3100ms) [1R 2R]"), (3100, R(1, 5, true), "Started(시작 3100ms) [1R 2R]"));
            return e ?? At(l, 5000, "Started(시작 3100ms) [1R 2R]", "제보 3 스크립트");
        });

        Run("leave-before-join", () =>
            Feed(new Lobby(), "3번의 나가기(seq 2)가 입장(seq 1)보다 먼저 도착", (0, J(1, 1), null), (0, J(2, 1), null), (50, L(3, 2), "Waiting [1_ 2_]"), (120, J(3, 1), "Waiting [1_ 2_]"),
                (200, R(1, 2, true), "Waiting [1R 2_]"), (250, R(2, 2, true), "Countdown(시작 3250ms) [1R 2R]"), (260, J(3, 1), "Countdown(시작 3250ms) [1R 2R]")));

        Run("stale-ready-reorder", () =>
            Feed(new Lobby(), "준비(seq 2)와 준비 해제(seq 3)가 뒤바뀌어 도착", (0, J(1, 1), null), (0, J(2, 1), null), (100, R(2, 2, true), "Waiting [1_ 2R]"),
                (300, R(1, 3, false), "Waiting [1_ 2R]"), (310, R(1, 2, true), "Waiting [1_ 2R]"), (320, R(1, 3, false), "Waiting [1_ 2R]"), (400, R(1, 4, true), "Countdown(시작 3400ms) [1R 2R]")));

        Run("countdown-cancel-rules", () =>
        {
            var l = new Lobby();
            return Feed(l, "3인 방의 카운트다운 취소와 재시작", (0, J(1, 1), null), (0, J(2, 1), null), (0, J(3, 1), null), (10, R(1, 2, true), null), (10, R(2, 2, true), null),
                    (20, R(3, 2, true), "Countdown(시작 3020ms) [1R 2R 3R]"), (500, R(2, 3, false), "Waiting [1R 2_ 3R]"), (900, R(2, 4, true), "Countdown(시작 3900ms) [1R 2R 3R]"),
                    (1500, L(3, 3), "Countdown(시작 3900ms) [1R 2R]"), (1600, J(4, 1), "Waiting [1R 2R 4_]"), (1700, L(4, 2), "Countdown(시작 4700ms) [1R 2R]"), (2000, L(2, 5), "Waiting [1R]"))
                ?? At(l, 9000, "Waiting [1R]", "인원이 1명으로 줄어든 뒤");
        });

        Run("started-ignores-late-messages", () =>
        {
            var l = new Lobby();
            return Feed(l, "시작 직후의 메시지", (0, J(1, 1), null), (0, J(2, 1), null), (100, R(1, 2, true), null), (100, R(2, 2, true), "Countdown(시작 3100ms) [1R 2R]"),
                    (3100, L(2, 3), "Started(시작 3100ms) [1R 2R]"), (3200, J(3, 1), "Started(시작 3100ms) [1R 2R]"))
                ?? At(l, 9000, "Started(시작 3100ms) [1R 2R]", "시작 뒤");
        });

        Run("random-vs-reference", () =>
        {
            _lcg = 99u;
            for (int run = 0; run < 400; run++)
            {
                var list = new System.Collections.Generic.List<(int at, int idx, PlayerMsg m)>();
                for (int p = 1; p <= 4; p++)
                {
                    int t = Next(300), seq = 0; bool inRoom = false, ready = false;
                    for (int k = 0, steps = 4 + Next(8); k < steps; k++)
                    {
                        int op = k == 0 ? 0 : Next(10);
                        if (op == 0) { inRoom = true; ready = false; } else if (op <= 4) { if (inRoom) ready = !ready; } else if (op <= 6) { } else if (op <= 8) { inRoom = !inRoom; ready = false; } else { inRoom = false; ready = false; }
                        var m = new PlayerMsg(p, ++seq, inRoom, ready);
                        list.Add((t + Next(400), list.Count, m));
                        if (Next(4) == 0) list.Add((t + Next(2500), list.Count, m));   // 재전송된 중복
                        t += 150 + Next(1200);
                    }
                }
                list.Sort((a, b) => a.at != b.at ? a.at.CompareTo(b.at) : a.idx.CompareTo(b.idx));
                var l = new Lobby(); var r = new Ref();
                foreach (var (at, idx, m) in list)
                {
                    l.Receive(m, at); r.Receive(m, at);
                    if (State(l) != r.State()) return run + "회차 " + at + "ms 에 P" + m.PlayerId + " seq " + m.Seq + (m.InRoom ? (m.Ready ? " 준비" : " 입장·준비 해제") : " 나가기") + " 도착 뒤 기대 " + r.State() + " / 결과 " + State(l);
                }
                l.Update(30000); r.Update(30000);
                if (State(l) != r.State()) return run + "회차 끝 기대 " + r.State() + " / 결과 " + State(l);
            }
            return null;
        });
    }
}

