{
    public const float MaxSpeed = 6f;                        // m/s, 이 게임에서 가장 빠른 정상 이동
    public const float BurstSeconds = 0.25f;                 // 지터 허용: 0.25초 분량까지는 몰려서 도착해도 된다
    public const float MaxBudget = MaxSpeed * BurstSeconds;  // 1.5 m
    public const float Epsilon = 0.001f;                     // 부동소수점 여유 1 mm

    private Vector2 _position;
    private double _budget;       // 지금 더 움직여도 되는 거리(m)
    private int _lastServerMs;

    // 호출자 보장: serverNowMs 는 서버의 단조 시계(ms)이고, 이후 호출에서 줄어들지 않는다.
    public MovementValidator(Vector2 spawnPosition, int serverNowMs)
    {
        _position = spawnPosition;
        _budget = MaxBudget;                                 // 처음에는 가득 찬 상태
        _lastServerMs = serverNowMs;
    }

    // 서버가 인정한 마지막 위치. Correct 를 돌려줄 때 클라이언트를 이 위치로 되돌린다.
    public Vector2 AuthoritativePosition => _position;

    // claimedPosition: 클라이언트가 보고한 현재 위치(조작될 수 있다, NaN·무한대 포함)
    // clientTimeMs: 클라이언트가 붙인 시각(조작될 수 있다)
    // serverNowMs: 서버가 이 패킷을 처리하는 시각. 호출자는 순서가 뒤바뀐 옛 위치 패킷을 이미 버렸다.
    public MoveVerdict OnMove(Vector2 claimedPosition, int clientTimeMs, int serverNowMs)
    {
        // 1) 시간이 흐른 만큼 예산을 채운다. 시간은 서버 시계만 쓴다(clientTimeMs 는 조작될 수 있다).
        int elapsedMs = serverNowMs - _lastServerMs;
        _lastServerMs = serverNowMs;
        _budget = Math.Min(MaxBudget, _budget + MaxSpeed * elapsedMs / 1000.0);

        // 2) 마지막으로 인정한 위치에서 얼마나 움직였다고 주장하는가.
        double distance = Vector2.Distance(claimedPosition, _position);

        // 3) "통과 조건" 을 직접 쓴다. NaN 은 어떤 비교도 참이 아니므로 자동으로 보정 쪽으로 간다.
        if (distance <= _budget + Epsilon)
        {
            _position = claimedPosition;
            _budget = Math.Max(0.0, _budget - distance);
            return MoveVerdict.Accept;
        }

        // 4) 보정: 위치와 예산은 그대로 두고, 호출자는 AuthoritativePosition 으로 되돌리라고 클라이언트에 보낸다.
        return MoveVerdict.Correct;
    }
}

// 스킬 하나의 재사용 대기시간을 서버 시계로 검사한다.
public sealed class CooldownValidator
{
    public const int ToleranceMs = 100;   // 도착 시각이 흔들려도 되는 폭

    private readonly int _cooldownMs;
    private long _readyAtMs;               // 다음 사용이 "원래" 가능한 시각. 처음에는 바로 쓸 수 있다.

    // 호출자 보장: cooldownMs > ToleranceMs, serverNowMs >= 0 이고 줄어들지 않는다.
    public CooldownValidator(int cooldownMs) { _cooldownMs = cooldownMs; }

    // 허용하면 true(스킬 발동), 거부하면 false(클라이언트에 남은 대기시간을 다시 알려 준다).
    public bool TryUse(int clientTimeMs, int serverNowMs)
    {
        if (serverNowMs < _readyAtMs - ToleranceMs) return false;   // 너무 이르다: 상태를 바꾸지 않는다
        // 일찍 허용된 만큼은 다음 대기시간에서 뺀다. 늦게 왔으면 도착 시각부터 다시 잰다.
        _readyAtMs = Math.Max(serverNowMs, _readyAtMs) + _cooldownMs;
        return true;
    }
}

