using System;
using System.Buffers.Binary;
using System.Text;

// 서버가 보내는 플레이어 프로필. 받은 패킷에 없는 필드는 아래 기본값을 쓴다.
public sealed class PlayerProfile
{
    public int Level = 1;
    public string Name = "";
}

// 패킷 = 레코드의 나열. 레코드 하나 = [필드 번호 1바이트][값 길이 2바이트, 리틀 엔디언][값 (길이)바이트]
//   필드 1 Level : int32 리틀 엔디언, 길이는 반드시 4
//   필드 2 Name  : UTF-8 문자열
//   그 밖의 번호 : 이 클라이언트(v1)가 모르는 필드. 길이만큼 건너뛴다.
public static class ProfileReader
{
    public const byte FieldLevel = 1;
    public const byte FieldName = 2;

    // 성공하면 true 와 프로필, 패킷이 깨졌으면 false 와 null. 예외를 던지지 않는다.
    public static bool TryRead(ReadOnlySpan<byte> data, out PlayerProfile profile)
    {
        profile = null;
        var result = new PlayerProfile();
        int pos = 0;
        while (pos < data.Length)
        {
            if (data.Length - pos < 3) return false;                          // 헤더(번호 + 길이)가 잘렸다
            byte field = data[pos];
            int length = BinaryPrimitives.ReadUInt16LittleEndian(data.Slice(pos + 1, 2));
            pos += 3;
            if (length > data.Length - pos) return false;                     // 값이 잘렸다(또는 길이가 조작됐다)
            ReadOnlySpan<byte> value = data.Slice(pos, length);
            pos += length;                                                    // 알든 모르든 다음 레코드로 간다

            if (field == FieldLevel)
            {
                if (length != 4) return false;                                // 아는 필드인데 형식이 다르다
                result.Level = BinaryPrimitives.ReadInt32LittleEndian(value);  // 같은 필드가 또 오면 마지막 값
            }
            else if (field == FieldName)
            {
                result.Name = Encoding.UTF8.GetString(value);
            }
            // 그 밖의 번호는 모르는 필드: 이미 길이만큼 건너뛰었다.
        }
        profile = result;
        return true;
    }
}

