using System;

// 서버가 매 틱 엔터티의 위치·생존 상태를 기록해 두고, 사격 명령을 "쏜 사람이 보던 시각"으로 되감아 판정한다.
public sealed class LagCompensator
{
    public const int MaxInterpMs = 100;   // 클라이언트가 알려 준 보간 지연은 0 ~ 100ms 로 자른다(이 게임의 규칙)
    public const int MaxRewindMs = 250;   // 서버 현재 시각에서 최대 250ms 까지만 되감는다(이 게임의 규칙)

    private readonly int _capacity;
    private readonly int[] _time;         // [entity * capacity + slot]
    private readonly float[] _x, _y;
    private readonly bool[] _alive;
    private readonly int[] _head;         // 엔터티마다 가장 오래된 샘플의 슬롯
    private readonly int[] _count;        // 엔터티마다 보관 중인 샘플 수(<= capacity)

    // 엔터티 id 는 0 .. entityCount-1, historyCapacity >= 1 은 엔터티마다 보관하는 샘플 수다.
    public LagCompensator(int entityCount, int historyCapacity)
    {
        _capacity = historyCapacity;
        int n = entityCount * historyCapacity;
        _time = new int[n]; _x = new float[n]; _y = new float[n]; _alive = new bool[n];
        _head = new int[entityCount]; _count = new int[entityCount];
    }

    // 서버 틱마다 엔터티마다 한 번 호출된다. 같은 엔터티의 timeMs 는 엄격히 증가한다(호출자 보장).
    public void Record(int entityId, int timeMs, float x, float y, bool alive)
    {
        int slot;
        if (_count[entityId] < _capacity) { slot = (_head[entityId] + _count[entityId]) % _capacity; _count[entityId]++; }
        else { slot = _head[entityId]; _head[entityId] = (slot + 1) % _capacity; }   // 가득 차면 가장 오래된 것을 덮어쓴다
        int i = entityId * _capacity + slot;
        _time[i] = timeMs; _x[i] = x; _y[i] = y; _alive[i] = alive;
    }

    // 규칙 1: 목표 시각 = 서버 현재 시각 − 왕복 지연 − 보간 지연(0 ~ 100 으로 자름), 단 250ms 보다 더 되감지 않는다.
    public static int RewindTargetMs(int serverNowMs, int rttMs, int clientInterpMs)
    {
        int interp = Math.Clamp(clientInterpMs, 0, MaxInterpMs);
        int target = serverNowMs - rttMs - interp;
        return Math.Max(target, serverNowMs - MaxRewindMs);
    }

    // 규칙 2: timeMs 시점의 상태. 보관한 샘플 범위 밖이면 가장 가까운 끝 샘플, 사이면 선형 보간(생존 여부는 앞 샘플).
    public bool TryGetStateAt(int entityId, int timeMs, out float x, out float y, out bool alive)
    {
        int count = _count[entityId];
        if (count == 0) { x = 0; y = 0; alive = false; return false; }
        int baseIndex = entityId * _capacity, head = _head[entityId];
        int a = baseIndex + head;                                  // 가장 오래된 샘플
        if (timeMs <= _time[a]) { x = _x[a]; y = _y[a]; alive = _alive[a]; return true; }
        for (int k = 1; k < count; k++)
        {
            int b = baseIndex + (head + k) % _capacity;
            if (timeMs < _time[b])                                 // a.time <= timeMs < b.time
            {
                double f = (double)(timeMs - _time[a]) / (_time[b] - _time[a]);
                x = (float)(_x[a] + (_x[b] - _x[a]) * f);
                y = (float)(_y[a] + (_y[b] - _y[a]) * f);
                alive = _alive[a];
                return true;
            }
            a = b;
        }
        x = _x[a]; y = _y[a]; alive = _alive[a];                   // 가장 최근 샘플 이후
        return true;
    }

    // 규칙 3: 되감은 시각의 히트 원들에 광선을 쏴서, 입사 거리가 가장 짧은 엔터티 id(같으면 작은 id)를 돌려준다. 없으면 -1.
    public int HitScan(int shooterId, float originX, float originY, float dirX, float dirY,
                       float range, float hitRadius, int serverNowMs, int rttMs, int clientInterpMs)
    {
        double len = Math.Sqrt((double)dirX * dirX + (double)dirY * dirY);
        if (len == 0) return -1;
        double dx = dirX / len, dy = dirY / len;
        int target = RewindTargetMs(serverNowMs, rttMs, clientInterpMs);

        int best = -1; double bestS = double.MaxValue;
        for (int id = 0; id < _count.Length; id++)
        {
            if (id == shooterId) continue;
            if (!TryGetStateAt(id, target, out float cx, out float cy, out bool alive) || !alive) continue;
            double ox = cx - (double)originX, oy = cy - (double)originY;   // 원점에서 원 중심으로
            double c2 = ox * ox + oy * oy - (double)hitRadius * hitRadius;
            double s;
            if (c2 <= 0) s = 0;                                    // 원점이 원 안: 바로 맞는다
            else
            {
                double b = ox * dx + oy * dy;                      // 광선 방향으로의 투영
                double disc = b * b - c2;
                if (b < 0 || disc < 0) continue;                   // 뒤쪽이거나 비껴감
                s = b - Math.Sqrt(disc);                           // 원에 들어가는 거리
            }
            if (s > range) continue;
            if (s < bestS) { bestS = s; best = id; }               // id 오름차순으로 도므로 같으면 작은 id 가 남는다
        }
        return best;
    }
}

