public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static string F(double v) => v.ToString("0.###");

    static string State(LagCompensator c, int id, int t, bool wantOk, float wx, float wy, bool walive, string ctx)
    {
        bool ok = c.TryGetStateAt(id, t, out float x, out float y, out bool alive);
        if (ok != wantOk) return ctx + ": 엔터티 " + id + ", " + t + "ms 조회 결과 기대 " + wantOk + " / 결과 " + ok;
        if (!ok) return null;
        if (System.Math.Abs(x - wx) > 1e-3 || System.Math.Abs(y - wy) > 1e-3 || alive != walive)
            return ctx + ": 엔터티 " + id + ", " + t + "ms 상태 기대 (" + F(wx) + ", " + F(wy) + ", alive=" + walive + ") / 결과 (" + F(x) + ", " + F(y) + ", alive=" + alive + ")";
        return null;
    }

    static string Shot(LagCompensator c, int shooter, float ox, float oy, float dx, float dy, float range, float r, int now, int rtt, int interp, int want, string ctx)
    {
        int got = c.HitScan(shooter, ox, oy, dx, dy, range, r, now, rtt, interp);
        return got == want ? null : ctx + ": HitScan(원점 (" + F(ox) + ", " + F(oy) + "), 방향 (" + F(dx) + ", " + F(dy) + "), 사거리 " + F(range) + ", 반지름 " + F(r) + ", now " + now + ", rtt " + rtt + ", interp " + interp + ") 기대 " + want + " / 결과 " + got;
    }

    // 기준 구현: 모든 샘플을 리스트에 쌓고 마지막 cap 개만 본다.
    sealed class Ref
    {
        readonly int cap; readonly System.Collections.Generic.List<(int t, float x, float y, bool a)>[] s;
        public Ref(int n, int cap) { this.cap = cap; s = new System.Collections.Generic.List<(int, float, float, bool)>[n]; for (int i = 0; i < n; i++) s[i] = new System.Collections.Generic.List<(int, float, float, bool)>(); }
        public void Rec(int id, int t, float x, float y, bool a) => s[id].Add((t, x, y, a));
        public bool Get(int id, int t, out double x, out double y, out bool a)
        {
            var l = s[id]; x = y = 0; a = false; if (l.Count == 0) return false;
            int lo = System.Math.Max(0, l.Count - cap);
            if (t <= l[lo].t) { x = l[lo].x; y = l[lo].y; a = l[lo].a; return true; }
            if (t >= l[l.Count - 1].t) { var z = l[l.Count - 1]; x = z.x; y = z.y; a = z.a; return true; }
            for (int i = lo; ; i++) if (l[i].t <= t && t < l[i + 1].t) { var p = l[i]; var q = l[i + 1]; double f = (t - p.t) / (double)(q.t - p.t); x = p.x + (q.x - p.x) * f; y = p.y + (q.y - p.y) * f; a = p.a; return true; }
        }
        // 맞은 id 와, 판정이 경계에 가까워 쓰기 곤란한지(ambiguous)를 함께 돌려준다.
        public int Hit(int shooter, double ox, double oy, double dx, double dy, double range, double r, int target, out bool ambiguous)
        {
            ambiguous = false; double L = System.Math.Sqrt(dx * dx + dy * dy); dx /= L; dy /= L;
            int best = -1; double bs = double.MaxValue, second = double.MaxValue;
            for (int id = 0; id < s.Length; id++)
            {
                if (id == shooter || !Get(id, target, out double cx, out double cy, out bool al) || !al) continue;
                double px = cx - ox, py = cy - oy, c2 = px * px + py * py - r * r, b = px * dx + py * dy, disc = b * b - c2;
                if (System.Math.Abs(c2) < 1e-2 || System.Math.Abs(disc) < 1e-2) ambiguous = true;
                if (c2 > 0 && (b < 0 || disc < 0)) continue;
                double sHit = c2 <= 0 ? 0 : b - System.Math.Sqrt(disc);
                if (System.Math.Abs(sHit - range) < 1e-2) ambiguous = true;
                if (sHit > range) continue;
                if (sHit < bs) { second = bs; bs = sHit; best = id; } else if (sHit < second) second = sHit;
            }
            if (best >= 0 && second - bs < 1e-2) ambiguous = true;
            return best;
        }
    }

    static int RefTarget(int now, int rtt, int interp) => System.Math.Max(now - rtt - System.Math.Min(100, System.Math.Max(0, interp)), now - 250);

    static uint _lcg;
    static int Next(int mod) { _lcg = unchecked(_lcg * 1664525u + 1013904223u); return (int)((_lcg >> 8) % (uint)mod); }

    public static void Main()
    {
        Run("rewind-target-formula", () =>
        {
            int[][] cs = { new[] { 1000, 80, 50, 870 }, new[] { 1000, 80, 500, 820 }, new[] { 1000, 80, -40, 920 }, new[] { 1000, 400, 50, 750 },
                           new[] { 1000, 0, 0, 1000 }, new[] { 1000, 150, 100, 750 }, new[] { 1000, 160, 100, 750 }, new[] { 5000, 30, 70, 4900 }, new[] { 300, 20, 100, 180 } };
            foreach (var k in cs) { int got = LagCompensator.RewindTargetMs(k[0], k[1], k[2]); if (got != k[3]) return "RewindTargetMs(now " + k[0] + ", rtt " + k[1] + ", interp " + k[2] + ") 기대 " + k[3] + " / 결과 " + got; }
            return null;
        });

        Run("state-interpolation", () =>
        {
            var c = new LagCompensator(3, 8);
            c.Record(0, 0, 0f, 0f, true); c.Record(0, 50, 10f, -5f, true); c.Record(0, 100, 10f, 20f, true); c.Record(0, 116, 26f, 20f, true);
            c.Record(1, 200, 3f, 4f, true);
            return State(c, 0, 20, true, 4f, -2f, true, "두 샘플 사이") ?? State(c, 0, 50, true, 10f, -5f, true, "샘플 시각과 정확히 같음")
                ?? State(c, 0, 75, true, 10f, 7.5f, true, "두 샘플 사이") ?? State(c, 0, 108, true, 18f, 20f, true, "간격이 16ms 인 구간")
                ?? State(c, 0, -30, true, 0f, 0f, true, "가장 오래된 샘플보다 이전") ?? State(c, 0, 130, true, 26f, 20f, true, "가장 최근 샘플 이후")
                ?? State(c, 1, 150, true, 3f, 4f, true, "샘플이 하나뿐") ?? State(c, 1, 900, true, 3f, 4f, true, "샘플이 하나뿐")
                ?? State(c, 2, 100, false, 0f, 0f, false, "기록이 없는 엔터티");
        });

        Run("bounded-history", () =>
        {
            var c = new LagCompensator(1, 3);
            for (int t = 0; t <= 400; t += 50) c.Record(0, t, t / 10f, -t / 20f, true);   // 보관되는 것은 300, 350, 400ms 뿐
            string e = State(c, 0, 320, true, 32f, -16f, true, "용량 3, 남은 구간 안") ?? State(c, 0, 100, true, 30f, -15f, true, "용량 3: 덮어쓴 100ms 샘플이 아니라 가장 오래 남은 300ms 샘플")
                ?? State(c, 0, 299, true, 30f, -15f, true, "용량 3: 250ms 와 300ms 사이를 보간하지 않는다") ?? State(c, 0, 1000, true, 40f, -20f, true, "가장 최근 이후");
            if (e != null) return e;
            var one = new LagCompensator(2, 1);
            for (int t = 0; t < 100; t += 10) { one.Record(1, t, t, 1f, true); }
            if ((e = State(one, 1, 0, true, 90f, 1f, true, "용량 1: 가장 최근 샘플만")) != null) return e;
            var w = new LagCompensator(2, 4);
            for (int k = 0; k < 1000; k++) { w.Record(0, k * 20, k, 0f, k % 2 == 0); w.Record(1, k * 20 + 5, -k, 2f, true); }
            return State(w, 0, 19950, true, 997.5f, 0f, false, "1000개 기록 뒤(링 버퍼를 여러 바퀴 돎)") ?? State(w, 0, 19930, true, 996.5f, 0f, true, "1000개 기록 뒤")
                ?? State(w, 0, 19000, true, 996f, 0f, true, "1000개 기록 뒤 남은 가장 오래된 샘플(19920ms)") ?? State(w, 1, 19955, true, -997.5f, 2f, true, "1000개 기록 뒤, 다른 엔터티");
        });

        Run("alive-state-rewind", () =>
        {
            var c = new LagCompensator(2, 16);
            c.Record(0, 0, 0f, 0f, true);
            bool[] al = { true, true, false, false, true, true }; float[] xs = { 10, 10, 10, 10, -50, -50 };
            for (int k = 0; k < 6; k++) c.Record(1, k * 50, xs[k], 0f, al[k]);
            return State(c, 1, 90, true, 10f, 0f, true, "100ms 샘플에서 죽음: 90ms 에는 살아 있다") ?? State(c, 1, 100, true, 10f, 0f, false, "100ms 에 죽음")
                ?? State(c, 1, 199, true, -48.8f, 0f, false, "150ms(죽음)와 200ms(부활) 사이") ?? State(c, 1, 200, true, -50f, 0f, true, "200ms 에 부활")
                ?? Shot(c, 0, 0f, 0f, 1f, 0f, 50f, 1f, 180, 60, 30, 1, "목표 시각 90ms: 아직 살아 있던 대상")
                ?? Shot(c, 0, 0f, 0f, 1f, 0f, 50f, 1f, 200, 60, 30, -1, "목표 시각 110ms: 이미 죽은 대상");
        });

        Run("hitscan-rewind-and-limits", () =>
        {
            var c = new LagCompensator(2, 64);
            for (int t = 0; t <= 1000; t += 20) { c.Record(0, t, 0f, 0f, true); c.Record(1, t, -5f + 0.01f * t, 20f, true); }  // 대상은 10 m/s 로 x 방향, 500ms 에 x = 0
            return Shot(c, 0, 0f, 0f, 0f, 1f, 100f, 0.3f, 620, 80, 40, 1, "목표 500ms: 쏜 사람이 보던 위치(x = 0)")
                ?? Shot(c, 0, 0f, 0f, 0f, 1f, 100f, 0.3f, 620, 0, 0, -1, "되감지 않으면(목표 620ms) 대상은 x = 1.2")
                ?? Shot(c, 0, 0f, 0f, 0f, 1f, 100f, 0.3f, 800, 250, 50, -1, "왕복 250 + 보간 50: 250ms 한도로 550ms(x = 0.5)까지만 되감는다")
                ?? Shot(c, 0, 0f, 0f, 0f, 1f, 100f, 0.3f, 800, 100, 200, -1, "보간 200ms 라는 주장은 100ms 로 잘린다(목표 600ms, x = 1)")
                ?? Shot(c, 0, 0f, 0f, 0f, 1f, 100f, 0.3f, 700, 100, 100, 1, "왕복 100 + 보간 100: 목표 500ms");
        });

        Run("hitscan-geometry", () =>
        {
            var c = new LagCompensator(7, 4);
            float[][] p = { new[] { 0f, 0f }, new[] { 10f, 0f }, new[] { 6f, 0.5f }, new[] { -5f, 0f }, new[] { 30f, 30f }, new[] { 0f, 8f }, new[] { 0f, 8f } };
            for (int i = 0; i < 7; i++) c.Record(i, 0, p[i][0], p[i][1], true);
            string e = Shot(c, 0, 0f, 0f, 1f, 0f, 100f, 1f, 100, 50, 50, 2, "가장 가까운 대상(쏜 사람 자신은 제외)")
                ?? Shot(c, 0, 0f, 0f, 3f, 0f, 4f, 1f, 100, 50, 50, -1, "방향 (3, 0), 사거리 4: 입사 거리 5.13 이라 밖")
                ?? Shot(c, 0, 0f, 0f, 0.5f, 0f, 6f, 1f, 100, 50, 50, 2, "방향 (0.5, 0), 사거리 6: 입사 거리 5.13")
                ?? Shot(c, 0, 0f, 0f, -1f, 0f, 100f, 1f, 100, 50, 50, 3, "뒤쪽(-x)의 대상")
                ?? Shot(c, 0, 0f, 0f, 0f, 1f, 100f, 1f, 100, 50, 50, 5, "같은 거리의 두 대상: 작은 id")
                ?? Shot(c, 0, 0f, 0f, 0f, 0f, 100f, 1f, 100, 50, 50, -1, "길이 0 인 방향");
            if (e != null) return e;
            var g = new LagCompensator(4, 2);
            g.Record(0, 0, 100f, 100f, true); g.Record(1, 0, 5f, 1f, true); g.Record(2, 0, 0.5f, 0f, true);
            return Shot(g, 0, 0f, 0f, 1f, 0f, 10f, 1f, 50, 0, 0, 2, "원점이 원 안인 대상(입사 거리 0)")
                ?? Shot(g, 0, 0f, 0f, -1f, 0f, 10f, 1f, 50, 0, 0, 2, "원점이 원 안이면 방향과 상관없이")
                ?? Shot(g, 0, 0f, -3f, 1f, 0f, 5f, 1f, 50, 0, 0, -1, "원점 (0, -3) 에서 +x: 모두 비껴감")
                ?? Shot(g, 0, 0f, 2f, 1f, 0f, 5f, 1f, 50, 0, 0, 1, "(5, 1) 원에 접하는 광선, 입사 거리 정확히 5 = 사거리")
                ?? Shot(g, 0, 0f, 2f, 1f, 0f, 4.99f, 1f, 50, 0, 0, -1, "사거리 4.99")
                ?? Shot(g, 0, 1f, 1f, 1f, 0f, 3.5f, 1f, 50, 0, 0, 1, "중심까지 4 지만 입사 거리 3 인 대상")
                ?? Shot(g, 3, 1f, 1f, 1f, 0f, 3.5f, 1f, 50, 0, 0, 1, "기록이 없는 엔터티(3)가 쏘아도 판정은 된다");
        });

        Run("random-vs-reference", () =>
        {
            _lcg = 2024u; int checkedShots = 0, checkedStates = 0;
            for (int scene = 0; scene < 120; scene++)
            {
                int n = 2 + Next(6), cap = 1 + Next(12); var c = new LagCompensator(n, cap); var r = new Ref(n, cap);
                int t = Next(100); int[] last = new int[n];
                for (int step = 0; step < 40; step++)
                {
                    t += 10 + Next(30);
                    for (int id = 0; id < n; id++)
                    {
                        if (Next(8) == 0) continue;   // 가끔 기록을 건너뛴다(엔터티마다 시각이 다르다)
                        float x = Next(4000) / 100f - 20f, y = Next(4000) / 100f - 20f; bool a = Next(6) != 0;
                        int tt = t + Next(5); c.Record(id, tt, x, y, a); r.Rec(id, tt, x, y, a);
                    }
                }
                for (int q = 0; q < 10; q++)
                {
                    int id = Next(n), qt = t - Next(cap * 45 + 60);
                    bool okR = r.Get(id, qt, out double wx, out double wy, out bool wa);
                    string e = State(c, id, qt, okR, (float)wx, (float)wy, wa, "무작위 장면 " + scene); if (e != null) return e; checkedStates++;
                }
                for (int q = 0; q < 15; q++)
                {
                    int now = t + Next(20), rtt = Next(300), interp = Next(300) - 50, shooter = Next(n);
                    float ox = Next(2000) / 100f - 10f, oy = Next(2000) / 100f - 10f, dx = Next(200) - 100, dy = Next(200) - 100, range = 5 + Next(40), rad = 0.5f + Next(30) / 10f;
                    if (Next(2) == 0 && r.Get(Next(n), RefTarget(now, rtt, interp), out double ax, out double ay, out bool _))   // 절반은 누군가의 되감은 위치를 노린다
                    { dx = (float)(ax - ox) + (Next(200) - 100) / 100f; dy = (float)(ay - oy) + (Next(200) - 100) / 100f; range = 60; }
                    if (dx == 0 && dy == 0) continue;
                    int want = r.Hit(shooter, ox, oy, dx, dy, range, rad, RefTarget(now, rtt, interp), out bool amb);
                    if (amb) continue;
                    string e = Shot(c, shooter, ox, oy, dx, dy, range, rad, now, rtt, interp, want, "무작위 장면 " + scene); if (e != null) return e; checkedShots++;
                }
            }
            return checkedShots > 800 && checkedStates == 1200 ? null : "테스트 생성 오류 (" + checkedShots + ", " + checkedStates + ")";
        });
    }
}

