using System;
using System.Collections.Generic;

public enum MsgKind { Spawn, Update, Despawn }

// 서버가 한 클라이언트(뷰어)에게 보내는 복제 메시지 하나.
public readonly struct NetMsg
{
    public readonly int Viewer;
    public readonly MsgKind Kind;
    public readonly int Entity;
    public NetMsg(int viewer, MsgKind kind, int entity) { Viewer = viewer; Kind = kind; Entity = entity; }
    public override string ToString() => Viewer + ":" + Kind + ":" + Entity;
}

// 필드 서버의 관심 영역(AOI) 관리자. 엔터티를 20m 격자 셀에 담아 두고, 틱마다 뷰어별로 Spawn/Update/Despawn 을 만든다.
public sealed class InterestManager
{
    public const float CellSize = 20f;
    public const float EnterRadius = 50f;
    public const float ExitRadius = 60f;

    private sealed class Entity { public float X, Y; }
    private sealed class Viewer { public int Id; public float X, Y; public HashSet<int> Known = new HashSet<int>(); }

    private readonly Dictionary<int, Entity> _entities = new Dictionary<int, Entity>();
    private readonly Dictionary<long, List<int>> _cells = new Dictionary<long, List<int>>();
    private readonly SortedDictionary<int, Viewer> _viewers = new SortedDictionary<int, Viewer>();
    private readonly List<int> _candidates = new List<int>();
    private HashSet<int> _seen = new HashSet<int>();

    private static long Key(int cx, int cy) => ((long)cx << 32) | (uint)cy;
    private static int CellOf(float v) => (int)MathF.Floor(v / CellSize);

    private List<int> Cell(float x, float y)
    {
        long k = Key(CellOf(x), CellOf(y));
        if (!_cells.TryGetValue(k, out var list)) { list = new List<int>(); _cells.Add(k, list); }
        return list;
    }

    public void AddEntity(int id, float x, float y)
    {
        _entities.Add(id, new Entity { X = x, Y = y });
        Cell(x, y).Add(id);
    }

    public void MoveEntity(int id, float x, float y)
    {
        var e = _entities[id];
        if (CellOf(e.X) != CellOf(x) || CellOf(e.Y) != CellOf(y))
            Cell(x, y).Add(id);
        e.X = x; e.Y = y;
    }

    public void RemoveEntity(int id)
    {
        var e = _entities[id];
        Cell(e.X, e.Y).Remove(id);
        _entities.Remove(id);
    }

    // 뷰어(접속한 클라이언트의 카메라 위치)를 추가하거나 옮긴다.
    public void SetViewer(int viewerId, float x, float y)
    {
        if (!_viewers.TryGetValue(viewerId, out var v)) { v = new Viewer { Id = viewerId }; _viewers.Add(viewerId, v); }
        v.X = x; v.Y = y;
    }

    // 디버그 통계: 모든 셀에 들어 있는 항목 수의 합.
    public int TotalBucketEntries
    {
        get { int n = 0; foreach (var list in _cells.Values) n += list.Count; return n; }
    }

    public void Tick(List<NetMsg> output)
    {
        foreach (var v in _viewers.Values)
        {
            _candidates.Clear();
            int x0 = CellOf(v.X - ExitRadius), x1 = CellOf(v.X + ExitRadius);
            int y0 = CellOf(v.Y - ExitRadius), y1 = CellOf(v.Y + ExitRadius);
            for (int cx = x0; cx <= x1; cx++)
                for (int cy = y0; cy <= y1; cy++)
                    if (_cells.TryGetValue(Key(cx, cy), out var list)) _candidates.AddRange(list);

            _seen.Clear();
            foreach (int id in _candidates)
            {
                if (!_entities.TryGetValue(id, out var e)) continue;
                bool known = v.Known.Contains(id);
                float limit = known ? EnterRadius : ExitRadius;
                float dx = e.X - v.X, dy = e.Y - v.Y;
                if (dx * dx + dy * dy <= limit * limit)
                {
                    output.Add(new NetMsg(v.Id, known ? MsgKind.Update : MsgKind.Spawn, id));
                    _seen.Add(id);
                }
                else if (known)
                {
                    output.Add(new NetMsg(v.Id, MsgKind.Despawn, id));
                }
            }
            (v.Known, _seen) = (_seen, v.Known);
        }
    }
}

