public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static readonly System.Collections.Generic.List<NetMsg> Buf = new System.Collections.Generic.List<NetMsg>();

    // 한 틱을 돌리고 메시지를 정렬된 문자열로 돌려준다(순서는 따지지 않고, 중복은 그대로 센다).
    static string TickStr(InterestManager m)
    {
        Buf.Clear(); m.Tick(Buf);
        var s = new System.Collections.Generic.List<string>(); foreach (var x in Buf) s.Add(x.Viewer + ":" + x.Kind + ":" + x.Entity);
        s.Sort(System.StringComparer.Ordinal); return "[" + string.Join(", ", s) + "]";
    }

    static string Expect(InterestManager m, string want, string ctx)
    {
        string got = TickStr(m);
        return got == want ? null : ctx + ": 기대 " + want + " / 결과 " + got;
    }

    // 기준 구현: 격자 없이 모든 엔터티를 매번 검사한다.
    sealed class Ref
    {
        public readonly System.Collections.Generic.SortedDictionary<int, (float x, float y)> E = new System.Collections.Generic.SortedDictionary<int, (float, float)>();
        public readonly System.Collections.Generic.SortedDictionary<int, (float x, float y, System.Collections.Generic.HashSet<int> known)> V = new System.Collections.Generic.SortedDictionary<int, (float, float, System.Collections.Generic.HashSet<int>)>();
        public string Tick()
        {
            var s = new System.Collections.Generic.List<string>();
            foreach (var kv in V)
            {
                var known = kv.Value.known; var next = new System.Collections.Generic.HashSet<int>();
                foreach (var e in E)
                {
                    float dx = e.Value.x - kv.Value.x, dy = e.Value.y - kv.Value.y; bool k = known.Contains(e.Key);
                    float lim = k ? 60f : 50f;
                    if (dx * dx + dy * dy <= lim * lim) { next.Add(e.Key); s.Add(kv.Key + ":" + (k ? "Update" : "Spawn") + ":" + e.Key); }
                }
                foreach (int id in known) if (!next.Contains(id)) s.Add(kv.Key + ":Despawn:" + id);
                known.Clear(); known.UnionWith(next);
            }
            s.Sort(System.StringComparer.Ordinal); return "[" + string.Join(", ", s) + "]";
        }
    }

    static uint _lcg;
    static int Next(int mod) { _lcg = unchecked(_lcg * 1664525u + 1013904223u); return (int)((_lcg >> 8) % (uint)mod); }

    public static void Main()
    {
        Run("enter-exit-hysteresis", () =>
        {
            var m = new InterestManager(); m.SetViewer(1, 0f, 0f); m.AddEntity(7, 57f, 0f);
            for (int t = 1; t <= 4; t++) if (Expect(m, "[]", "57m 에 서 있는 상자(50m 안에 들어온 적 없음), " + t + "번째 틱") is string e) return e;
            m.AddEntity(8, 45f, 0f);
            float[] path = { 45f, 55f, 59.75f, 60f, 60.25f, 52f, 50f };
            string[] want = { "[1:Spawn:8]", "[1:Update:8]", "[1:Update:8]", "[1:Update:8]", "[1:Despawn:8]", "[]", "[1:Spawn:8]" };
            for (int k = 0; k < path.Length; k++) { m.MoveEntity(8, path[k], 0f); if (Expect(m, want[k], "다가왔다 멀어지는 몬스터, x = " + path[k]) is string e) return e; }
            return null;
        });

        Run("jitter-no-flicker", () =>
        {
            var m = new InterestManager(); m.SetViewer(3, 100f, 100f); m.AddEntity(5, 149f, 100f);
            if (Expect(m, "[3:Spawn:5]", "49m 에서 처음 보임") is string e0) return e0;
            float[] jitter = { 0f, 4.5f, 9f, 6f, 1f, 8.75f, 3f, 10f };
            for (int k = 0; k < 24; k++)
            {
                m.SetViewer(3, 100f - jitter[k % 8], 100f + (k % 3) * 0.5f);
                if (Expect(m, "[3:Update:5]", "뷰어가 0 ~ 10m 흔들림(거리 49 ~ 59m), " + (k + 1) + "번째 틱") is string e) return e;
            }
            return null;
        });

        Run("removed-entity-despawned", () =>
        {
            var m = new InterestManager(); m.SetViewer(1, 0f, 0f); m.SetViewer(2, 300f, 0f);
            m.AddEntity(40, 10f, 0f); m.AddEntity(41, 290f, 5f); m.AddEntity(42, 20f, -20f);
            string e = Expect(m, "[1:Spawn:40, 1:Spawn:42, 2:Spawn:41]", "첫 틱");
            if (e != null) return e;
            m.RemoveEntity(40);
            return Expect(m, "[1:Despawn:40, 1:Update:42, 2:Update:41]", "몬스터 40 이 죽어 제거된 다음 틱")
                ?? Expect(m, "[1:Update:42, 2:Update:41]", "그다음 틱(Despawn 은 한 번만)");
        });

        Run("teleport-out-despawned", () =>
        {
            var m = new InterestManager(); m.SetViewer(1, 0f, 0f); m.AddEntity(9, -30f, 10f); m.AddEntity(10, 5f, 5f);
            string e = Expect(m, "[1:Spawn:10, 1:Spawn:9]", "첫 틱");
            if (e != null) return e;
            m.MoveEntity(9, 500f, 500f);
            if ((e = Expect(m, "[1:Despawn:9, 1:Update:10]", "엔터티 9 가 마을로 귀환(500, 500)")) != null) return e;
            m.SetViewer(1, -1000f, 0f);
            return Expect(m, "[1:Despawn:10]", "뷰어가 순간이동해 멀어짐");
        });

        Run("cell-cross-single-message", () =>
        {
            var m = new InterestManager(); m.SetViewer(1, 0f, 0f); m.AddEntity(20, 19f, 5f); m.AddEntity(21, 65f, 0f);
            string e = Expect(m, "[1:Spawn:20]", "첫 틱");
            if (e != null) return e;
            m.MoveEntity(20, 21f, 5f); m.MoveEntity(21, 45f, 0f);
            if ((e = Expect(m, "[1:Spawn:21, 1:Update:20]", "20 은 셀 0 → 1, 21 은 셀 3 → 2 로 경계를 넘음")) != null) return e;
            m.MoveEntity(20, -21f, -5f); m.MoveEntity(21, 39f, 0f);
            return Expect(m, "[1:Update:20, 1:Update:21]", "다시 경계를 넘음(음수 좌표 포함)");
        });

        Run("bucket-bookkeeping", () =>
        {
            var m = new InterestManager(); _lcg = 11u;
            for (int id = 0; id < 30; id++) m.AddEntity(id, Next(400) - 200, Next(400) - 200);
            for (int k = 0; k < 2000; k++) m.MoveEntity(Next(30), Next(400) - 200, Next(400) - 200);
            if (m.TotalBucketEntries != 30) return "엔터티 30개가 2000번 움직인 뒤 셀 항목 수 기대 30 / 결과 " + m.TotalBucketEntries;
            for (int id = 0; id < 30; id += 3) m.RemoveEntity(id);
            return m.TotalBucketEntries == 20 ? null : "10개를 제거한 뒤 셀 항목 수 기대 20 / 결과 " + m.TotalBucketEntries;
        });

        Run("random-vs-reference", () =>
        {
            _lcg = 99u;
            for (int run = 0; run < 25; run++)
            {
                var m = new InterestManager(); var r = new Ref(); int nextId = 100;
                for (int v = 0; v < 3; v++) { float x = (Next(800) - 400) / 4f, y = (Next(800) - 400) / 4f; m.SetViewer(v, x, y); r.V[v] = (x, y, new System.Collections.Generic.HashSet<int>()); }
                for (int tick = 0; tick < 60; tick++)
                {
                    for (int op = 0; op < 6; op++)
                    {
                        int kind = Next(10);
                        if (kind == 0 || r.E.Count < 3) { float x = (Next(1000) - 500) / 4f, y = (Next(1000) - 500) / 4f; m.AddEntity(nextId, x, y); r.E[nextId++] = (x, y); }
                        else if (kind == 1) { int id = new System.Collections.Generic.List<int>(r.E.Keys)[Next(r.E.Count)]; m.RemoveEntity(id); r.E.Remove(id); }
                        else if (kind == 2) { int v = Next(3); float x = r.V[v].x + (Next(161) - 80) / 4f, y = r.V[v].y + (Next(161) - 80) / 4f; m.SetViewer(v, x, y); r.V[v] = (x, y, r.V[v].known); }
                        else { int id = new System.Collections.Generic.List<int>(r.E.Keys)[Next(r.E.Count)]; var p = r.E[id]; float x = p.x + (Next(81) - 40) / 4f, y = p.y + (Next(81) - 40) / 4f; if (Next(15) == 0) { x = -x; y = -y; } m.MoveEntity(id, x, y); r.E[id] = (x, y); }
                    }
                    string want = r.Tick(), got = TickStr(m);
                    if (got != want) return run + "회차 " + tick + "번째 틱 기대 " + want + " / 결과 " + got;
                }
            }
            return null;
        });
    }
}

