    private readonly Dictionary<int, (int cx, int cy)> _anchor = new Dictionary<int, (int, int)>();
    private readonly Dictionary<(int, int), List<int>> _byAnchor = new Dictionary<(int, int), List<int>>();

    // 셀 번호. 음수 좌표도 바닥 함수로: -0.5 는 -1 번 셀이다.
    public static int CellOf(float v) => (int)MathF.Floor(v / CellSize);

    // 플레이어를 추가하거나 옮긴다. 기준 셀은 히스테리시스 규칙으로만 바뀐다.
    public void UpdatePlayer(int playerId, float x, float y)
    {
        if (_anchor.TryGetValue(playerId, out var a))
        {
            float minX = a.cx * CellSize - Margin, maxX = (a.cx + 1) * CellSize + Margin;
            float minY = a.cy * CellSize - Margin, maxY = (a.cy + 1) * CellSize + Margin;
            if (x >= minX && x <= maxX && y >= minY && y <= maxY) return;   // 여유 띠 안: 그대로
            Bucket(a).Remove(playerId);
        }
        var next = (CellOf(x), CellOf(y));                                 // 지금 서 있는 셀로 바꾼다
        _anchor[playerId] = next;
        Bucket(next).Add(playerId);
    }

    public void RemovePlayer(int playerId)
    {
        if (_anchor.TryGetValue(playerId, out var a)) { Bucket(a).Remove(playerId); _anchor.Remove(playerId); }
    }

    public (int cx, int cy) AnchorOf(int playerId) => _anchor[playerId];

    // (x, y) 에 있는 엔터티의 업데이트를 받아야 하는 플레이어 id 를 오름차순으로 result 에 채운다.
    public void GetReceivers(float x, float y, List<int> result)
    {
        result.Clear();
        int ex = CellOf(x), ey = CellOf(y);
        for (int cx = ex - 1; cx <= ex + 1; cx++)          // 엔터티 셀이 기준 셀의 3×3 안 ⇔ 기준 셀이 엔터티 셀의 3×3 안
            for (int cy = ey - 1; cy <= ey + 1; cy++)
                if (_byAnchor.TryGetValue((cx, cy), out var list)) result.AddRange(list);
        result.Sort();                                     // 플레이어는 기준 셀 하나에만 있으므로 중복이 없다
    }

    private List<int> Bucket((int, int) cell)
    {
        if (!_byAnchor.TryGetValue(cell, out var list)) { list = new List<int>(); _byAnchor.Add(cell, list); }
        return list;
    }
}

