            for (int k = 0; k < 50; k++) g.UpdatePlayer(1, k % 2 == 0 ? 10f : 210f, 10f);
            return ExpectRecv(g, 220f, 20f, "[1, 3]", "플레이어 1 이 두 곳을 50번 오간 뒤(중복 없음)");
        });

        Run("random-vs-reference", () =>
        {
            _lcg = 31u;
            for (int run = 0; run < 30; run++)
            {
                var g = new AoiGrid(); var pos = new System.Collections.Generic.Dictionary<int, (int ax, int ay)>();
                var live = new System.Collections.Generic.Dictionary<int, (float x, float y)>();
                for (int step = 0; step < 300; step++)
                {
                    int id = Next(12); int op = Next(20);
                    if (op == 0) { g.RemovePlayer(id); live.Remove(id); pos.Remove(id); continue; }
                    float x, y;
                    if (!live.TryGetValue(id, out var p) || op == 1) { x = (Next(1600) - 800) / 4f; y = (Next(1600) - 800) / 4f; }
                    else { x = p.x + (Next(41) - 20) / 4f; y = p.y + (Next(41) - 20) / 4f; }
                    live[id] = (x, y);
                    if (pos.TryGetValue(id, out var a) && x >= a.ax * 32 - 4 && x <= a.ax * 32 + 36 && y >= a.ay * 32 - 4 && y <= a.ay * 32 + 36) { }
                    else pos[id] = (RefCell(x), RefCell(y));
                    g.UpdatePlayer(id, x, y);
                    var got = g.AnchorOf(id);
                    if (got.cx != pos[id].ax || got.cy != pos[id].ay) return run + "회차 " + step + "번째: 플레이어 " + id + " 를 (" + x + ", " + y + ") 로 옮긴 뒤 기준 셀 기대 (" + pos[id].ax + ", " + pos[id].ay + ") / 결과 (" + got.cx + ", " + got.cy + ")";
                    float ex = (Next(1600) - 800) / 4f, ey = (Next(1600) - 800) / 4f;
                    if (Next(2) == 0) { ex = x + (Next(161) - 80) / 2f; ey = y + (Next(161) - 80) / 2f; }
                    var want = new System.Collections.Generic.List<int>();
                    foreach (var kv in pos) if (System.Math.Abs(kv.Value.ax - RefCell(ex)) <= 1 && System.Math.Abs(kv.Value.ay - RefCell(ey)) <= 1) want.Add(kv.Key);
