using System;

// ---- 제공 코드: 바꾸지 마세요. 정수만 쓰는 결정론적 시뮬레이션 ----
public sealed class TinySim
{
    public readonly int Players;
    public int Turn;                 // 실행한 턴 수
    public readonly int[] X, Y, Hp;

    public TinySim(int players)
    {
        Players = players; X = new int[players]; Y = new int[players]; Hp = new int[players];
        for (int p = 0; p < players; p++) { X[p] = p * 10; Y[p] = 0; Hp[p] = 100; }
    }

    // command: 0 = 대기, 1~4 = 상하좌우 이동, 5 = 다음 플레이어 공격(피해 = 내 체력 / 10)
    public void Apply(int player, int command)
    {
        switch (command)
        {
            case 1: Y[player]++; break;
            case 2: Y[player]--; break;
            case 3: X[player]--; break;
            case 4: X[player]++; break;
            case 5: { int t = (player + 1) % Players; Hp[t] -= Hp[player] / 10; if (Hp[t] < 0) Hp[t] = 0; break; }
        }
    }

    public void EndTurn()
    {
        Turn++;
        for (int p = 0; p < Players; p++) if (Hp[p] > 0 && Hp[p] < 100) Hp[p]++;   // 살아 있으면 턴마다 1 회복
    }

    // 상태 전체의 FNV-1a(32비트) 체크섬. 모든 정수를 리틀 엔디언 4바이트로 넣는다.
    public uint Checksum()
    {
        uint h = 2166136261u;
        void Add(int v) { for (int i = 0; i < 4; i++) { h ^= (byte)(v >> (8 * i)); h *= 16777619u; } }
        Add(Turn);
        for (int p = 0; p < Players; p++) { Add(X[p]); Add(Y[p]); Add(Hp[p]); }
        return h;
    }
}
// ---- 제공 코드 끝 ----

// 결정론적 락스텝 턴 관리자: 모든 플레이어의 입력이 모인 턴만 실행하고, 턴마다 상태 체크섬을 비교한다.
public sealed class LockstepTurnManager
{
    public const int MaxAheadTurns = 32;   // NextTurn 부터 이만큼 앞까지의 입력·체크섬만 받는다
    public const int HistoryTurns = 32;    // 실행한 턴의 체크섬을 이만큼 뒤까지 보관한다

    private readonly int _players;
    private readonly TinySim _sim;
    private readonly int[] _inputTurn, _inputCmd;      // [슬롯 * players + p], 슬롯 = turn % MaxAheadTurns
    private readonly int[] _localTurn;                 // 슬롯 = turn % HistoryTurns
    private readonly uint[] _localSum;
    private readonly int[] _remoteTurn;                // 아직 실행하지 않은 턴의 원격 체크섬, 슬롯 = turn % MaxAheadTurns
    private readonly uint[] _remoteSum;

    public LockstepTurnManager(int playerCount, TinySim sim)
    {
        _players = playerCount; _sim = sim;
        _inputTurn = Filled(MaxAheadTurns * playerCount); _inputCmd = new int[MaxAheadTurns * playerCount];
        _localTurn = Filled(HistoryTurns); _localSum = new uint[HistoryTurns];
        _remoteTurn = Filled(MaxAheadTurns * playerCount); _remoteSum = new uint[MaxAheadTurns * playerCount];
        DesyncTurn = -1;
    }

    private static int[] Filled(int n) { var a = new int[n]; for (int i = 0; i < n; i++) a[i] = -1; return a; }

    public int NextTurn { get; private set; }
    public int DesyncTurn { get; private set; }

    // NextTurn 에 아직 입력이 오지 않은 플레이어의 비트 마스크(플레이어 p 는 1 << p).
    public int WaitingMask
    {
        get
        {
            int mask = 0, slot = NextTurn % MaxAheadTurns;
            for (int p = 0; p < _players; p++) if (_inputTurn[slot * _players + p] != NextTurn) mask |= 1 << p;
            return mask;
        }
    }

    // 규칙 1: 범위 안의 처음 오는 입력만 받는다. 받았으면 true.
    public bool SubmitInput(int player, int turn, int command)
    {
        if (player < 0 || player >= _players) return false;
        if (turn < NextTurn || turn >= NextTurn + MaxAheadTurns) return false;   // 이미 실행했거나 너무 먼 미래
        int i = (turn % MaxAheadTurns) * _players + player;
        if (_inputTurn[i] == turn) return false;                                 // 중복(재전송): 처음 값을 유지
        _inputTurn[i] = turn; _inputCmd[i] = command;
        return true;
    }

    // 규칙 3: 원격 체크섬. 실행한 턴이면 바로 비교, 아직이면 보관했다가 실행할 때 비교한다.
    public void SubmitChecksum(int player, int turn, uint checksum)
    {
        if (player < 0 || player >= _players || turn < 0) return;              // 없는 플레이어, 음수 턴
        if (turn < NextTurn)
        {
            if (turn < NextTurn - HistoryTurns) return;                            // 너무 오래되어 비교할 수 없다
            int s = turn % HistoryTurns;
            if (_localTurn[s] == turn && _localSum[s] != checksum) ReportDesync(turn);
            return;
        }
        if (turn >= NextTurn + MaxAheadTurns) return;
        int i = (turn % MaxAheadTurns) * _players + player;
        _remoteTurn[i] = turn; _remoteSum[i] = checksum;
    }

    // 규칙 2: 입력이 모두 모인 턴을 순서대로 최대 maxTurns 개 실행하고 실행한 수를 돌려준다.
    public int Advance(int maxTurns)
    {
        int done = 0;
        while (done < maxTurns && DesyncTurn < 0 && WaitingMask == 0)
        {
            int t = NextTurn, slot = t % MaxAheadTurns;
            for (int p = 0; p < _players; p++) _sim.Apply(p, _inputCmd[slot * _players + p]);   // 플레이어 번호 순서로
            _sim.EndTurn();
            uint sum = _sim.Checksum();
            _localTurn[t % HistoryTurns] = t; _localSum[t % HistoryTurns] = sum;
            for (int p = 0; p < _players; p++)
            {
                int i = slot * _players + p;
                if (_remoteTurn[i] == t && _remoteSum[i] != sum) ReportDesync(t);
                _inputTurn[i] = -1; _remoteTurn[i] = -1;                         // 슬롯을 다음 바퀴에 쓸 수 있게 비운다
            }
            NextTurn = t + 1;
            done++;
        }
        return done;
    }

    private void ReportDesync(int turn) { if (DesyncTurn < 0 || turn < DesyncTurn) DesyncTurn = turn; }
}

