public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    // 기준: 플레이어 순서대로 입력을 적용한 시뮬레이션의 턴별 체크섬.
    static uint[] RefSums(int players, int[,] cmds, int turns)
    {
        var s = new TinySim(players); var sums = new uint[turns];
        for (int t = 0; t < turns; t++) { for (int p = 0; p < players; p++) s.Apply(p, cmds[t, p]); s.EndTurn(); sums[t] = s.Checksum(); }
        return sums;
    }

    // 기준 관리자: 사전으로 같은 규칙을 그대로 옮긴 것.
    sealed class RefMgr
    {
        readonly int n; readonly TinySim sim; public int Next, Desync = -1;
        readonly System.Collections.Generic.Dictionary<(int, int), int> inp = new System.Collections.Generic.Dictionary<(int, int), int>();
        readonly System.Collections.Generic.Dictionary<(int, int), uint> rem = new System.Collections.Generic.Dictionary<(int, int), uint>();
        readonly System.Collections.Generic.Dictionary<int, uint> loc = new System.Collections.Generic.Dictionary<int, uint>();
        public RefMgr(int n) { this.n = n; sim = new TinySim(n); }
        public bool In(int p, int t, int c) { if (p < 0 || p >= n || t < Next || t >= Next + 32 || inp.ContainsKey((p, t))) return false; inp[(p, t)] = c; return true; }
        public void Sum(int p, int t, uint c) { if (p < 0 || p >= n || t < 0) return; if (t < Next) { if (t >= Next - 32 && loc[t] != c) Bad(t); return; } if (t < Next + 32) rem[(p, t)] = c; }
        void Bad(int t) { if (Desync < 0 || t < Desync) Desync = t; }
        public int Mask() { int m = 0; for (int p = 0; p < n; p++) if (!inp.ContainsKey((p, Next))) m |= 1 << p; return m; }
        public int Adv(int max)
        {
            int d = 0;
            while (d < max && Desync < 0 && Mask() == 0)
            {
                for (int p = 0; p < n; p++) sim.Apply(p, inp[(p, Next)]); sim.EndTurn(); uint s = sim.Checksum(); loc[Next] = s;
                for (int p = 0; p < n; p++) if (rem.TryGetValue((p, Next), out uint r) && r != s) Bad(Next);
                Next++; d++;
            }
            return d;
        }
    }

    static string State(LockstepTurnManager m, int next, int mask, int desync, string ctx)
