                var m = new LockstepTurnManager(n, new TinySim(n)); var r = new RefMgr(n);
                var events = new System.Collections.Generic.List<(int at, int kind, int p, int t)>();
                for (int t = 0; t < turns; t++) for (int p = 0; p < n; p++)
                {
                    events.Add((t * 3 + Next(4), 0, p, t));                           // 제때 도착하는 사본 하나
                    for (int k = Next(3); k > 0; k--) events.Add((t * 3 - Next(Next(6) == 0 ? 150 : 10) + Next(30), 0, p, t));   // 재전송 사본: 너무 이르거나 늦을 수 있다
