                int step = 0;
                foreach (var ev in events)
                {
                    step++;
                    if (ev.kind == 0)
                    {
                        bool w = r.In(ev.p, ev.t, cmds[ev.t, ev.p]), g = m.SubmitInput(ev.p, ev.t, cmds[ev.t, ev.p]);
                        if (w != g) return run + "회차 " + step + "번째 사건: 플레이어 " + ev.p + " 의 턴 " + ev.t + " 입력(NextTurn " + r.Next + ") 기대 " + w + " / 결과 " + g;
