                    else { uint c = ev.t == badTurn && ev.p == 0 ? sums[ev.t] ^ 1u : sums[ev.t]; r.Sum(ev.p, ev.t, c); m.SubmitChecksum(ev.p, ev.t, c); }
                    if (Next(3) == 0) { int mx = 1 + Next(4); int w = r.Adv(mx), g = m.Advance(mx); if (w != g) return run + "회차 " + step + "번째 사건 뒤 Advance(" + mx + ") 기대 " + w + " / 결과 " + g; }
                    string e = State(m, r.Next, r.Mask(), r.Desync, run + "회차 " + step + "번째 사건 뒤");
                    if (e != null) return e;
                }
            }
            return null;
        });
    }
}

