problems.solutionCode:
using System;

// 한 번의 요청·응답으로 얻은 추정값.
public readonly struct SyncSample
{
    public readonly double OffsetMs;   // 서버 시계 − 클라이언트 시계의 추정
    public readonly double DelayMs;    // 왕복 지연(서버 안에서 머문 시간은 뺀 값)
    public SyncSample(double offsetMs, double delayMs) { OffsetMs = offsetMs; DelayMs = delayMs; }
}

public static class TimeSync
{
    // t1: 클라이언트가 요청을 보낸 시각(클라이언트 시계)   t2: 서버가 요청을 받은 시각(서버 시계)
    // t3: 서버가 응답을 보낸 시각(서버 시계)               t4: 클라이언트가 응답을 받은 시각(클라이언트 시계)
    public static SyncSample Compute(double t1, double t2, double t3, double t4)
    {
        double offset = ((t2 - t1) + (t3 - t4)) / 2.0;   // RFC 5905 의 theta
        double delay = (t4 - t1) - (t3 - t2);            // RFC 5905 의 delta
        return new SyncSample(offset, delay);
    }
}

// 최근 8개 표본 가운데 왕복 지연이 가장 작은 표본의 오프셋을 쓴다(NTP 시계 필터를 단순화한 것).
public sealed class ServerClock
{
    public const int Window = 8;
    private readonly SyncSample[] _samples = new SyncSample[Window];
    private int _count, _next;              // _next: 다음에 쓸 칸(가장 오래된 표본을 덮어쓴다)

    public void AddSample(double t1, double t2, double t3, double t4)
    {
        var s = TimeSync.Compute(t1, t2, t3, t4);
        if (!(s.DelayMs >= 0)) return;      // 음수·NaN 지연은 타임스탬프가 잘못된 것이므로 버린다
        _samples[_next] = s;
        _next = (_next + 1) % Window;
        if (_count < Window) _count++;
    }

    public bool HasEstimate => _count > 0;

    // 표본이 없으면 0. 지연이 같으면 더 최근 표본.
    public double OffsetMs
    {
        get
        {
            if (_count == 0) return 0;
            int best = -1;
            for (int k = 1; k <= _count; k++)                       // 최근 것부터 거꾸로
            {
                int i = (_next - k + Window) % Window;
                if (best < 0 || _samples[i].DelayMs < _samples[best].DelayMs) best = i;
            }
            return _samples[best].OffsetMs;
        }
    }

    // 클라이언트의 단조 시계(예: Stopwatch) 값을 서버 시각 추정으로 바꾼다.
    public double ToServerTime(double localMs) => localMs + OffsetMs;
}
